const esbuild = require('esbuild');
const path = require('path');
const fs = require('fs');

async function build() {
  const isProd = process.env.NODE_ENV === 'production';

  if (!fs.existsSync(path.join(__dirname, 'public'))) {
    fs.mkdirSync(path.join(__dirname, 'public'), { recursive: true });
  }

  // Build TypeScript
  await esbuild.build({
    entryPoints: [path.join(__dirname, 'frontend/src/index.ts')],
    bundle: true,
    outfile: path.join(__dirname, 'public/bundle.js'),
    sourcemap: true,
    minify: isProd,
    target: ['es2022'],
    platform: 'browser',
    define: {
      'process.env.NODE_ENV': JSON.stringify(process.env.NODE_ENV || 'development'),
    },
  });

  console.log('Build completed successfully.');
}

if (require.main === module) {
  build().catch((err) => {
    console.error('Build failed:', err);
    process.exit(1);
  });
}

module.exports = { build };

const Database = require('better-sqlite3');
const path = require('path');
const fs = require('fs');
const crypto = require('crypto');

const DB_PATH = process.env.DB_PATH || path.join(__dirname, '../pellmoor.db');
const SEED_FILE = path.join(__dirname, '../../recruitment/records/pellmoor_seed_data.json');

let dbInstance = null;

function getDb(customPath = null) {
  const targetPath = customPath || DB_PATH;
  if (!dbInstance || (customPath && dbInstance.name !== targetPath)) {
    const dir = path.dirname(targetPath);
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }
    dbInstance = new Database(targetPath);
    dbInstance.pragma('journal_mode = WAL');
    dbInstance.pragma('foreign_keys = ON');
    initSchema(dbInstance);
  }
  return dbInstance;
}

function initSchema(db) {
  db.exec(`
    CREATE TABLE IF NOT EXISTS people (
      email TEXT PRIMARY KEY,
      name TEXT NOT NULL,
      role TEXT NOT NULL,
      password TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS sessions (
      token TEXT PRIMARY KEY,
      user_email TEXT NOT NULL,
      created_at TEXT NOT NULL,
      expires_at TEXT NOT NULL,
      FOREIGN KEY (user_email) REFERENCES people(email) ON DELETE CASCADE
    );

    CREATE TABLE IF NOT EXISTS vacancies (
      code TEXT PRIMARY KEY,
      title TEXT NOT NULL,
      team TEXT NOT NULL,
      openings INTEGER NOT NULL,
      revision INTEGER NOT NULL DEFAULT 1
    );

    CREATE TABLE IF NOT EXISTS candidates (
      id TEXT PRIMARY KEY,
      vacancy_code TEXT NOT NULL,
      name TEXT NOT NULL,
      stage TEXT NOT NULL,
      days_since_applied INTEGER NOT NULL DEFAULT 0,
      assessment_version INTEGER NOT NULL DEFAULT 1,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL,
      FOREIGN KEY (vacancy_code) REFERENCES vacancies(code) ON DELETE RESTRICT
    );

    CREATE TABLE IF NOT EXISTS candidate_stage_history (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      candidate_id TEXT NOT NULL,
      stage TEXT NOT NULL,
      sequence_order INTEGER NOT NULL,
      created_at TEXT NOT NULL,
      FOREIGN KEY (candidate_id) REFERENCES candidates(id) ON DELETE CASCADE
    );

    CREATE TABLE IF NOT EXISTS panel_assignments (
      candidate_id TEXT NOT NULL,
      member_email TEXT NOT NULL,
      created_at TEXT NOT NULL,
      PRIMARY KEY (candidate_id, member_email),
      FOREIGN KEY (candidate_id) REFERENCES candidates(id) ON DELETE CASCADE,
      FOREIGN KEY (member_email) REFERENCES people(email) ON DELETE CASCADE
    );

    CREATE TABLE IF NOT EXISTS scores (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      candidate_id TEXT NOT NULL,
      assessment_version INTEGER NOT NULL,
      scorer_email TEXT NOT NULL,
      score INTEGER NOT NULL,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL,
      UNIQUE(candidate_id, assessment_version, scorer_email),
      FOREIGN KEY (candidate_id) REFERENCES candidates(id) ON DELETE CASCADE,
      FOREIGN KEY (scorer_email) REFERENCES people(email) ON DELETE CASCADE
    );

    CREATE TABLE IF NOT EXISTS notes (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      candidate_id TEXT NOT NULL,
      author_email TEXT NOT NULL,
      author_name TEXT NOT NULL,
      text TEXT NOT NULL,
      created_at TEXT NOT NULL,
      FOREIGN KEY (candidate_id) REFERENCES candidates(id) ON DELETE CASCADE,
      FOREIGN KEY (author_email) REFERENCES people(email) ON DELETE CASCADE
    );

    CREATE TABLE IF NOT EXISTS activity_log (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      vacancy_code TEXT NOT NULL,
      candidate_id TEXT,
      actor_email TEXT NOT NULL,
      actor_name TEXT NOT NULL,
      action_type TEXT NOT NULL,
      description TEXT NOT NULL,
      details_json TEXT NOT NULL,
      created_at TEXT NOT NULL,
      FOREIGN KEY (vacancy_code) REFERENCES vacancies(code) ON DELETE RESTRICT
    );

    CREATE TABLE IF NOT EXISTS operation_receipts (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_email TEXT NOT NULL,
      operation_key TEXT NOT NULL,
      method TEXT NOT NULL,
      path TEXT NOT NULL,
      payload_hash TEXT NOT NULL,
      status_code INTEGER NOT NULL,
      response_json TEXT NOT NULL,
      created_at TEXT NOT NULL,
      UNIQUE(user_email, operation_key),
      FOREIGN KEY (user_email) REFERENCES people(email) ON DELETE CASCADE
    );

    CREATE INDEX IF NOT EXISTS idx_candidates_vacancy ON candidates(vacancy_code);
    CREATE INDEX IF NOT EXISTS idx_history_candidate ON candidate_stage_history(candidate_id, sequence_order);
    CREATE INDEX IF NOT EXISTS idx_scores_candidate ON scores(candidate_id, assessment_version);
    CREATE INDEX IF NOT EXISTS idx_notes_candidate ON notes(candidate_id);
    CREATE INDEX IF NOT EXISTS idx_activity_vacancy ON activity_log(vacancy_code, id);
    CREATE INDEX IF NOT EXISTS idx_activity_candidate ON activity_log(candidate_id, id);
  `);

  // Check if seed data needs to be populated
  const peopleCount = db.prepare('SELECT COUNT(*) as count FROM people').get().count;
  if (peopleCount === 0 && fs.existsSync(SEED_FILE)) {
    seedDatabase(db);
  }
}

function seedDatabase(db, seedPath = SEED_FILE) {
  const seedRaw = fs.readFileSync(seedPath, 'utf8');
  const seed = JSON.parse(seedRaw);
  const now = seed.clock || new Date().toISOString();

  const insertPeople = db.prepare('INSERT OR REPLACE INTO people (email, name, role, password) VALUES (?, ?, ?, ?)');
  const insertVacancy = db.prepare('INSERT OR REPLACE INTO vacancies (code, title, team, openings, revision) VALUES (?, ?, ?, ?, 1)');
  const insertCandidate = db.prepare('INSERT OR REPLACE INTO candidates (id, vacancy_code, name, stage, days_since_applied, assessment_version, created_at, updated_at) VALUES (?, ?, ?, ?, ?, 1, ?, ?)');
  const insertHistory = db.prepare('INSERT INTO candidate_stage_history (candidate_id, stage, sequence_order, created_at) VALUES (?, ?, ?, ?)');
  const insertPanel = db.prepare('INSERT OR IGNORE INTO panel_assignments (candidate_id, member_email, created_at) VALUES (?, ?, ?)');
  const insertScore = db.prepare('INSERT OR REPLACE INTO scores (candidate_id, assessment_version, scorer_email, score, created_at, updated_at) VALUES (?, 1, ?, ?, ?, ?)');
  const insertActivity = db.prepare('INSERT INTO activity_log (vacancy_code, candidate_id, actor_email, actor_name, action_type, description, details_json, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)');

  const tx = db.transaction(() => {
    // 1. People
    for (const p of seed.people) {
      insertPeople.run(p.email, p.name, p.role, seed.seed_password || 'password123');
    }

    // 2. Roles / Vacancies
    for (const r of seed.roles) {
      insertVacancy.run(r.code, r.title, r.team, r.openings);
    }

    // 3. Candidates and history
    if (seed.candidates) {
      for (const c of seed.candidates) {
        insertCandidate.run(c.id, c.role, c.name, c.stage, c.days_since_applied || 0, now, now);
        if (c.history && Array.isArray(c.history)) {
          c.history.forEach((stage, idx) => {
            insertHistory.run(c.id, stage, idx + 1, now);
          });
        } else {
          insertHistory.run(c.id, c.stage, 1, now);
        }
      }
    }

    // 4. Panel assignments
    if (seed.panels) {
      for (const p of seed.panels) {
        for (const member of p.members) {
          insertPanel.run(p.candidate, member, now);
        }
      }
    }

    // 5. Scores (version 1)
    if (seed.scores) {
      for (const s of seed.scores) {
        insertScore.run(s.candidate, s.panel_member, s.score, now, now);
      }
    }
  });

  tx();
}

function canonicalStringify(val) {
  if (val === null || typeof val !== 'object') {
    return JSON.stringify(val);
  }
  if (Array.isArray(val)) {
    return '[' + val.map(canonicalStringify).join(',') + ']';
  }
  const keys = Object.keys(val).sort();
  return '{' + keys.map(k => JSON.stringify(k) + ':' + canonicalStringify(val[k])).join(',') + '}';
}

function computePayloadHash(method, pathUrl, body) {
  const normMethod = (method || '').toUpperCase();
  const normPath = (pathUrl || '').split('?')[0];
  const normBody = canonicalStringify(body || {});
  return crypto.createHash('sha256').update(`${normMethod}|${normPath}|${normBody}`).digest('hex');
}

module.exports = {
  getDb,
  initSchema,
  seedDatabase,
  canonicalStringify,
  computePayloadHash,
  DB_PATH
};

const STAGES = ['applied', 'screening', 'interview', 'offer', 'hired'];
const TERMINAL_STAGES = ['rejected', 'withdrawn'];
const ELIGIBLE_PANEL_MEMBERS = ['hiring@pellmoor.test', 'panel1@pellmoor.test', 'panel2@pellmoor.test'];
const HIRING_MANAGER_EMAIL = 'hiring@pellmoor.test';

function getCapacity(db, vacancyCode) {
  const vacancy = db.prepare('SELECT openings, revision FROM vacancies WHERE code = ?').get(vacancyCode);
  if (!vacancy) return null;

  const reservedRow = db.prepare(`
    SELECT COUNT(*) as count FROM candidates WHERE vacancy_code = ? AND stage = 'offer'
  `).get(vacancyCode);
  const filledRow = db.prepare(`
    SELECT COUNT(*) as count FROM candidates WHERE vacancy_code = ? AND stage = 'hired'
  `).get(vacancyCode);

  const reserved = reservedRow ? reservedRow.count : 0;
  const filled = filledRow ? filledRow.count : 0;
  const openings = vacancy.openings;
  const available = Math.max(0, openings - reserved - filled);

  return {
    openings,
    reserved,
    filled,
    available,
    revision: vacancy.revision
  };
}

function calculateFunnel(db, vacancyCode) {
  const funnel = {
    applied: { reached: 0, remain: 0, lost: 0 },
    screening: { reached: 0, remain: 0, lost: 0 },
    interview: { reached: 0, remain: 0, lost: 0 },
    offer: { reached: 0, remain: 0, lost: 0 },
    hired: { reached: 0, remain: 0, lost: 0 },
  };

  const candidates = db.prepare('SELECT id, stage FROM candidates WHERE vacancy_code = ?').all(vacancyCode);
  const getHistory = db.prepare('SELECT stage FROM candidate_stage_history WHERE candidate_id = ? ORDER BY sequence_order ASC');

  for (const cand of candidates) {
    const historyRows = getHistory.all(cand.id);
    const history = historyRows.map(r => r.stage);

    // 1. Reached
    const reachedSet = new Set();
    for (const st of history) {
      if (STAGES.includes(st)) {
        reachedSet.add(st);
      }
    }
    for (const st of reachedSet) {
      if (funnel[st]) {
        funnel[st].reached += 1;
      }
    }

    // 2. Remain
    if (STAGES.includes(cand.stage)) {
      if (funnel[cand.stage]) {
        funnel[cand.stage].remain += 1;
      }
    }

    // 3. Lost
    if (TERMINAL_STAGES.includes(cand.stage)) {
      // Find the last visited pipeline stage in history
      let lastPipelineStage = null;
      for (let i = history.length - 1; i >= 0; i--) {
        if (STAGES.includes(history[i])) {
          lastPipelineStage = history[i];
          break;
        }
      }
      if (lastPipelineStage && funnel[lastPipelineStage]) {
        funnel[lastPipelineStage].lost += 1;
      }
    }
  }

  return funnel;
}

function evaluateOfferEligibility(candidate, panelMembers, currentScores, availableCapacity) {
  const reasons = [];

  if (candidate.stage !== 'interview') {
    reasons.push(`Candidate is not at interview stage (currently ${candidate.stage})`);
  }

  if (!panelMembers || panelMembers.length < 2) {
    reasons.push(`Panel requires at least 2 distinct members (currently ${panelMembers ? panelMembers.length : 0})`);
  } else {
    // Check if panel consists only of hiring manager
    const nonHiringManager = panelMembers.filter(m => m !== HIRING_MANAGER_EMAIL);
    if (nonHiringManager.length === 0) {
      reasons.push('Panel cannot consist only of the hiring manager');
    }

    // Check for invalid panel members
    for (const m of panelMembers) {
      if (!ELIGIBLE_PANEL_MEMBERS.includes(m)) {
        reasons.push(`Ineligible panel member assigned: ${m}`);
      }
    }
  }

  // Check scores for all current panel members in the candidate's current assessment version
  const currentScoresMap = new Map();
  for (const s of currentScores) {
    if (s.assessment_version === candidate.assessment_version) {
      currentScoresMap.set(s.scorer_email, s.score);
    }
  }

  if (panelMembers) {
    for (const m of panelMembers) {
      const score = currentScoresMap.get(m);
      if (score === undefined || score === null) {
        reasons.push(`Missing score from panel member ${m} for assessment version ${candidate.assessment_version}`);
      } else if (!Number.isInteger(score) || score < 1 || score > 5) {
        reasons.push(`Invalid score ${score} from panel member ${m}`);
      }
    }
  }

  if (availableCapacity < 1) {
    reasons.push('Vacancy has no available openings');
  }

  return {
    eligible: reasons.length === 0,
    reasons
  };
}

function validateStageTransition(currentStage, targetStage) {
  if (TERMINAL_STAGES.includes(currentStage)) {
    return { valid: false, error: `Candidate is in terminal stage '${currentStage}' and cannot be moved` };
  }

  if (currentStage === targetStage) {
    return { valid: false, error: `Candidate is already in stage '${currentStage}'` };
  }

  // Terminal move is allowed from any non-terminal stage
  if (TERMINAL_STAGES.includes(targetStage)) {
    return { valid: true, isTerminal: true };
  }

  const currIdx = STAGES.indexOf(currentStage);
  const targetIdx = STAGES.indexOf(targetStage);

  if (currIdx === -1 || targetIdx === -1) {
    return { valid: false, error: `Unknown stage '${targetStage}'` };
  }

  // Forward move: +1 only
  if (targetIdx === currIdx + 1) {
    return { valid: true, isForward: true };
  }

  // Backward move: -1 only
  if (targetIdx === currIdx - 1) {
    return { valid: true, isBackstep: true };
  }

  if (targetIdx > currIdx) {
    return { valid: false, error: `Cannot skip stages: moving from '${currentStage}' to '${targetStage}' is not allowed` };
  } else {
    return { valid: false, error: `Cannot jump back more than one stage: moving from '${currentStage}' to '${targetStage}' is not allowed` };
  }
}

module.exports = {
  STAGES,
  TERMINAL_STAGES,
  ELIGIBLE_PANEL_MEMBERS,
  HIRING_MANAGER_EMAIL,
  getCapacity,
  calculateFunnel,
  evaluateOfferEligibility,
  validateStageTransition
};

const crypto = require('crypto');
const { getDb } = require('./db');

function generateToken() {
  return crypto.randomBytes(32).toString('hex');
}

function createSession(userEmail) {
  const db = getDb();
  const token = generateToken();
  const now = new Date();
  const expiresAt = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000); // 7 days

  db.prepare(`
    INSERT INTO sessions (token, user_email, created_at, expires_at)
    VALUES (?, ?, ?, ?)
  `).run(token, userEmail, now.toISOString(), expiresAt.toISOString());

  return token;
}

function revokeSession(token) {
  if (!token) return;
  const db = getDb();
  db.prepare('DELETE FROM sessions WHERE token = ?').run(token);
}

function getSessionUser(token) {
  if (!token) return null;
  const db = getDb();
  const row = db.prepare(`
    SELECT s.token, s.expires_at, p.email, p.name, p.role
    FROM sessions s
    JOIN people p ON s.user_email = p.email
    WHERE s.token = ?
  `).get(token);

  if (!row) return null;

  if (new Date(row.expires_at) < new Date()) {
    revokeSession(token);
    return null;
  }

  return {
    email: row.email,
    name: row.name,
    role: row.role
  };
}

function authMiddleware(req, res, next) {
  let token = null;
  const authHeader = req.headers.authorization;
  if (authHeader && authHeader.startsWith('Bearer ')) {
    token = authHeader.substring(7).trim();
  } else if (req.cookies && req.cookies.session_token) {
    token = req.cookies.session_token;
  }

  if (!token) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const user = getSessionUser(token);
  if (!user) {
    return res.status(401).json({ error: 'Invalid or expired session' });
  }

  req.user = user;
  req.sessionToken = token;
  next();
}

function requireRole(...roles) {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Authentication required' });
    }
    if (!roles.includes(req.user.role)) {
      return res.status(403).json({ error: `Action unauthorized for role '${req.user.role}'` });
    }
    next();
  };
}

module.exports = {
  generateToken,
  createSession,
  revokeSession,
  getSessionUser,
  authMiddleware,
  requireRole
};

const FORBIDDEN_WRITE_FIELDS = new Set([
  'history',
  'stage_history',
  'funnel',
  'attribution',
  'revision',
  'revisions',
  'assessment_version',
  'capacity',
  'reserved',
  'filled',
  'available',
  'days_since_applied',
  'created_at',
  'updated_at'
]);

function checkForServerOwnedFields(body, allowedFields = []) {
  if (!body || typeof body !== 'object') return null;

  for (const key of Object.keys(body)) {
    if (FORBIDDEN_WRITE_FIELDS.has(key)) {
      return `Server-owned field '${key}' cannot be supplied in client write requests`;
    }
  }

  // If allowedFields is provided, ensure only allowed fields (plus expected_revision, operation_id, idempotency_key) are present
  if (allowedFields && allowedFields.length > 0) {
    const allowed = new Set([...allowedFields, 'expected_revision', 'operation_id', 'idempotency_key']);
    for (const key of Object.keys(body)) {
      if (!allowed.has(key)) {
        return `Unexpected or server-owned field '${key}' in write request`;
      }
    }
  }

  return null;
}

function parseExpectedRevision(req) {
  // Check header first
  const ifMatch = req.headers['if-match'];
  const headerRevision = req.headers['x-expected-revision'] || (ifMatch ? ifMatch.replace(/"/g, '') : null);

  if (headerRevision !== null && headerRevision !== undefined) {
    if (!/^\d+$/.test(String(headerRevision).trim())) {
      return { error: 'Malformed revision in request header: must be a non-negative integer' };
    }
    return { revision: parseInt(String(headerRevision).trim(), 10) };
  }

  // Check JSON body
  if (req.body && 'expected_revision' in req.body) {
    const rev = req.body.expected_revision;
    if (typeof rev !== 'number' || !Number.isInteger(rev) || rev < 0) {
      return { error: 'Invalid expected_revision in JSON body: must be a non-negative integer number' };
    }
    return { revision: rev };
  }

  // If revision is required and not provided
  return { revision: null };
}

function getOperationKey(req) {
  const headerKey = req.headers['idempotency-key'] || req.headers['x-operation-id'];
  if (headerKey) return String(headerKey).trim();
  if (req.body && (req.body.idempotency_key || req.body.operation_id)) {
    return String(req.body.idempotency_key || req.body.operation_id).trim();
  }
  return null;
}

module.exports = {
  FORBIDDEN_WRITE_FIELDS,
  checkForServerOwnedFields,
  parseExpectedRevision,
  getOperationKey
};

const express = require('express');
const { getDb } = require('../db');
const { createSession, revokeSession, authMiddleware } = require('../auth');

const router = express.Router();

router.post('/login', (req, res) => {
  const { email, password } = req.body || {};
  if (!email || !password) {
    return res.status(400).json({ error: 'Email and password are required' });
  }

  const db = getDb();
  const person = db.prepare('SELECT email, name, role, password FROM people WHERE email = ?').get(email.trim().toLowerCase());

  if (!person || person.password !== password) {
    return res.status(401).json({ error: 'Invalid email or password' });
  }

  const token = createSession(person.email);
  return res.json({
    token,
    user: {
      email: person.email,
      name: person.name,
      role: person.role
    }
  });
});

router.post('/logout', authMiddleware, (req, res) => {
  revokeSession(req.sessionToken);
  return res.json({ success: true, message: 'Logged out successfully' });
});

router.get('/me', authMiddleware, (req, res) => {
  return res.json({
    user: req.user
  });
});

router.get('/people', authMiddleware, (req, res) => {
  const db = getDb();
  const people = db.prepare('SELECT email, name, role FROM people').all();
  return res.json({ people });
});

module.exports = router;

const { getDb, computePayloadHash } = require('./db');
const { getOperationKey } = require('./validation');

function handleIdempotency(req, res, next) {
  const opKey = getOperationKey(req);
  if (!opKey || !req.user) {
    return next();
  }

  const db = getDb();
  const existing = db.prepare(`
    SELECT status_code, response_json, payload_hash
    FROM operation_receipts
    WHERE user_email = ? AND operation_key = ?
  `).get(req.user.email, opKey);

  if (existing) {
    const currentHash = computePayloadHash(req.method, req.originalUrl, req.body);
    if (existing.payload_hash === currentHash) {
      let parsedResponse;
      try {
        parsedResponse = JSON.parse(existing.response_json);
      } catch (e) {
        parsedResponse = { message: existing.response_json };
      }
      return res.status(existing.status_code).json(parsedResponse);
    } else {
      return res.status(409).json({
        error: 'Operation key mismatch: this operation identity was previously used with different parameters or payload array ordering.'
      });
    }
  }

  // Attach a helper to save receipt
  res.saveReceipt = (statusCode, responseBody) => {
    try {
      const payloadHash = computePayloadHash(req.method, req.originalUrl, req.body);
      const now = new Date().toISOString();
      db.prepare(`
        INSERT OR REPLACE INTO operation_receipts
        (user_email, operation_key, method, path, payload_hash, status_code, response_json, created_at)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?)
      `).run(
        req.user.email,
        opKey,
        (req.method || '').toUpperCase(),
        (req.originalUrl || '').split('?')[0],
        payloadHash,
        statusCode,
        JSON.stringify(responseBody),
        now
      );
    } catch (e) {
      console.error('Error saving operation receipt:', e);
    }
  };

  next();
}

function sendResponseWithReceipt(res, statusCode, body) {
  if (res.saveReceipt) {
    res.saveReceipt(statusCode, body);
  }
  return res.status(statusCode).json(body);
}

module.exports = {
  handleIdempotency,
  sendResponseWithReceipt
};

const { STAGES, TERMINAL_STAGES, ELIGIBLE_PANEL_MEMBERS, getCapacity, calculateFunnel, evaluateOfferEligibility } = require('./rules');

function getVacancySummary(db, vacancyCode) {
  const v = db.prepare('SELECT code, title, team, openings, revision FROM vacancies WHERE code = ?').get(vacancyCode);
  if (!v) return null;

  const capacity = getCapacity(db, vacancyCode);
  const countRow = db.prepare('SELECT COUNT(*) as count FROM candidates WHERE vacancy_code = ?').get(vacancyCode);

  return {
    code: v.code,
    title: v.title,
    team: v.team,
    openings: v.openings,
    revision: v.revision,
    reserved: capacity.reserved,
    filled: capacity.filled,
    available: capacity.available,
    candidate_count: countRow ? countRow.count : 0
  };
}

function getAllVacancies(db) {
  const rows = db.prepare('SELECT code FROM vacancies ORDER BY code ASC').all();
  return rows.map(r => getVacancySummary(db, r.code));
}

function getCandidateDetails(db, candidateId) {
  const cand = db.prepare(`
    SELECT c.id, c.vacancy_code, c.name, c.stage, c.days_since_applied, c.assessment_version, c.created_at, c.updated_at
    FROM candidates c
    WHERE c.id = ?
  `).get(candidateId);

  if (!cand) return null;

  // History
  const historyRows = db.prepare(`
    SELECT stage FROM candidate_stage_history
    WHERE candidate_id = ?
    ORDER BY sequence_order ASC
  `).all(cand.id);
  const history = historyRows.map(r => r.stage);

  // Panel
  const panelRows = db.prepare(`
    SELECT pa.member_email, p.name as member_name
    FROM panel_assignments pa
    LEFT JOIN people p ON pa.member_email = p.email
    WHERE pa.candidate_id = ?
    ORDER BY pa.member_email ASC
  `).all(cand.id);
  const panel = panelRows.map(p => ({
    email: p.member_email,
    name: p.member_name || p.member_email
  }));
  const panelEmails = panel.map(p => p.email);

  // Scores
  const scoreRows = db.prepare(`
    SELECT s.assessment_version, s.scorer_email, s.score, p.name as scorer_name, s.created_at, s.updated_at
    FROM scores s
    LEFT JOIN people p ON s.scorer_email = p.email
    WHERE s.candidate_id = ?
    ORDER BY s.assessment_version DESC, s.scorer_email ASC
  `).all(cand.id);

  const currentScores = [];
  const historicalScores = [];

  for (const s of scoreRows) {
    const item = {
      assessment_version: s.assessment_version,
      scorer_email: s.scorer_email,
      scorer_name: s.scorer_name || s.scorer_email,
      score: s.score,
      created_at: s.created_at,
      updated_at: s.updated_at
    };
    if (s.assessment_version === cand.assessment_version) {
      currentScores.push(item);
    } else {
      historicalScores.push(item);
    }
  }

  // Notes
  const notesRows = db.prepare(`
    SELECT id, author_email, author_name, text, created_at
    FROM notes
    WHERE candidate_id = ?
    ORDER BY id ASC
  `).all(cand.id);

  // Capacity & Eligibility
  const capacity = getCapacity(db, cand.vacancy_code);
  const eligibility = evaluateOfferEligibility(cand, panelEmails, scoreRows, capacity.available);

  const isFrozen = ['offer', 'hired', 'rejected', 'withdrawn'].includes(cand.stage);
  const isTerminal = ['rejected', 'withdrawn'].includes(cand.stage);

  return {
    id: cand.id,
    vacancy_code: cand.vacancy_code,
    name: cand.name,
    stage: cand.stage,
    days_since_applied: cand.days_since_applied,
    assessment_version: cand.assessment_version,
    history,
    panel,
    current_scores: currentScores,
    historical_scores: historicalScores,
    notes: notesRows,
    offer_eligibility: eligibility,
    is_frozen: isFrozen,
    is_terminal: isTerminal,
    created_at: cand.created_at,
    updated_at: cand.updated_at
  };
}

function getVacancyFullDetails(db, vacancyCode) {
  const summary = getVacancySummary(db, vacancyCode);
  if (!summary) return null;

  const funnel = calculateFunnel(db, vacancyCode);

  const candidateRows = db.prepare('SELECT id FROM candidates WHERE vacancy_code = ? ORDER BY id ASC').all(vacancyCode);
  const candidates = candidateRows.map(r => getCandidateDetails(db, r.id));

  const activityRows = db.prepare(`
    SELECT id, vacancy_code, candidate_id, actor_email, actor_name, action_type, description, details_json, created_at
    FROM activity_log
    WHERE vacancy_code = ?
    ORDER BY id DESC
    LIMIT 100
  `).all(vacancyCode);

  const activity = activityRows.map(a => {
    let details = {};
    try {
      details = JSON.parse(a.details_json);
    } catch (e) {
      details = {};
    }
    return {
      id: a.id,
      vacancy_code: a.vacancy_code,
      candidate_id: a.candidate_id,
      actor_email: a.actor_email,
      actor_name: a.actor_name,
      action_type: a.action_type,
      description: a.description,
      details,
      created_at: a.created_at
    };
  });

  return {
    vacancy: summary,
    funnel,
    candidates,
    activity
  };
}

