export type Role = 'hiring manager' | 'panel' | 'coordinator';

export type Stage = 'applied' | 'screening' | 'interview' | 'offer' | 'hired' | 'rejected' | 'withdrawn';

export interface User {
  email: string;
  name: string;
  role: Role;
}

export interface VacancySummary {
  code: string;
  title: string;
  team: string;
  openings: number;
  revision: number;
  reserved: number;
  filled: number;
  available: number;
  candidate_count: number;
}

export interface FunnelStageData {
  reached: number;
  remain: number;
  lost: number;
}

export interface FunnelData {
  applied: FunnelStageData;
  screening: FunnelStageData;
  interview: FunnelStageData;
  offer: FunnelStageData;
  hired: FunnelStageData;
}

export interface PanelMember {
  email: string;
  name: string;
}

export interface ScoreRecord {
  assessment_version: number;
  scorer_email: string;
  scorer_name: string;
  score: number;
  created_at: string;
  updated_at: string;
}

export interface NoteRecord {
  id: number;
  author_email: string;
  author_name: string;
  text: string;
  created_at: string;
}

export interface OfferEligibility {
  eligible: boolean;
  reasons: string[];
}

export interface Candidate {
  id: string;
  vacancy_code: string;
  name: string;
  stage: Stage;
  days_since_applied: number;
  assessment_version: number;
  history: Stage[];
  panel: PanelMember[];
  current_scores: ScoreRecord[];
  historical_scores: ScoreRecord[];
  notes: NoteRecord[];
  offer_eligibility: OfferEligibility;
  is_frozen: boolean;
  is_terminal: boolean;
  created_at: string;
  updated_at: string;
}

export interface ActivityEvent {
  id: number;
  vacancy_code: string;
  candidate_id: string | null;
  actor_email: string;
  actor_name: string;
  action_type: string;
  description: string;
  details: Record<string, any>;
  created_at: string;
}

export interface VacancyFullDetails {
  vacancy: VacancySummary;
  funnel: FunnelData;
  candidates: Candidate[];
  activity: ActivityEvent[];
}

export interface BatchCandidatePreview {
  id: string;
  name: string;
  stage: string;
  assessment_version: number;
  eligible: boolean;
  reasons: string[];
}

export interface BatchPreviewResponse {
  vacancy_code: string;
  selected_count: number;
  current_capacity: {
    openings: number;
    reserved: number;
    filled: number;
    available: number;
    revision: number;
  };
  projected_capacity: {
    openings: number;
    reserved: number;
    filled: number;
    available: number;
  };
  candidates: BatchCandidatePreview[];
  batch_eligible: boolean;
  batch_ineligible_reasons: string[];
}

import {
  User,
  VacancySummary,
  VacancyFullDetails,
  Candidate,
  BatchPreviewResponse
} from './types';

let authToken: string | null = localStorage.getItem('pellmoor_auth_token');

export function setToken(token: string | null) {
  authToken = token;
  if (token) {
    localStorage.setItem('pellmoor_auth_token', token);
  } else {
    localStorage.removeItem('pellmoor_auth_token');
  }
}

export function getToken(): string | null {
  return authToken || localStorage.getItem('pellmoor_auth_token');
}

export function generateOperationId(): string {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) {
    return crypto.randomUUID();
  }
  return 'op-' + Math.random().toString(36).substring(2, 11) + '-' + Date.now().toString(36);
}

export interface ApiError {
  status: number;
  message: string;
  reasons?: string[];
  currentRevision?: number;
  data?: any;
}

async function apiRequest<T>(
  method: string,
  path: string,
  options: {
    body?: any;
    expectedRevision?: number;
    operationId?: string;
  } = {}
): Promise<T> {
  const headers: Record<string, string> = {
    'Accept': 'application/json'
  };

  const token = getToken();
  if (token) {
    headers['Authorization'] = `Bearer ${token}`;
  }

  if (options.operationId) {
    headers['Idempotency-Key'] = options.operationId;
  }

  if (options.expectedRevision !== undefined && options.expectedRevision !== null) {
    headers['X-Expected-Revision'] = String(options.expectedRevision);
  }

  let bodyData: string | undefined = undefined;
  if (options.body) {
    headers['Content-Type'] = 'application/json';
    const payload = { ...options.body };
    if (options.expectedRevision !== undefined && options.expectedRevision !== null && !('expected_revision' in payload)) {
      payload.expected_revision = options.expectedRevision;
    }
    bodyData = JSON.stringify(payload);
  }

  const res = await fetch(path, {
    method,
    headers,
    body: bodyData
  });

  let responseData: any = null;
  const contentType = res.headers.get('content-type') || '';
  if (contentType.includes('application/json')) {
    try {
      responseData = await res.json();
    } catch (e) {
      responseData = null;
    }
  } else {
    responseData = await res.text();
  }

  if (!res.ok) {
    const errorMsg = (responseData && typeof responseData === 'object' && responseData.error)
      ? responseData.error
      : `Request failed with status ${res.status}`;
    const err: ApiError = {
      status: res.status,
      message: errorMsg,
      reasons: responseData?.reasons,
      currentRevision: responseData?.current_revision,
      data: responseData
    };
    throw err;
  }

  return responseData as T;
}

// Auth APIs
export async function login(email: string, password: string): Promise<{ token: string; user: User }> {
  const res = await apiRequest<{ token: string; user: User }>('POST', '/api/auth/login', {
    body: { email, password }
  });
  setToken(res.token);
  return res;
}

export async function logout(): Promise<void> {
  try {
    await apiRequest('POST', '/api/auth/logout');
  } finally {
    setToken(null);
  }
}

export async function fetchCurrentUser(): Promise<User | null> {
  if (!getToken()) return null;
  try {
    const res = await apiRequest<{ user: User }>('GET', '/api/auth/me');
    return res.user;
  } catch (err: any) {
    if (err.status === 401) {
      setToken(null);
    }
    return null;
  }
}

export async function fetchPeople(): Promise<Array<{ email: string; name: string; role: string }>> {
  const res = await apiRequest<{ people: Array<{ email: string; name: string; role: string }> }>('GET', '/api/auth/people');
  return res.people;
}

// Vacancy APIs
export async function fetchVacancies(): Promise<VacancySummary[]> {
  const res = await apiRequest<{ vacancies: VacancySummary[] }>('GET', '/api/vacancies');
  return res.vacancies;
