import {
  VacancySummary,
  VacancyFullDetails,
  Candidate,
  User,
  Stage
} from '../types';
import { renderFunnel } from './funnel';

export interface VacancyViewCallbacks {
  onSelectVacancy: (code: string) => void;
  onOpenCandidate: (candidate: Candidate) => void;
  onOpenAddCandidate: () => void;
  onOpenBatchOffers: () => void;
  onRefresh: () => void;
}

const STAGES_LIST: Stage[] = ['applied', 'screening', 'interview', 'offer', 'hired', 'rejected', 'withdrawn'];

export class VacancyView {
  private container: HTMLElement;
  private vacancies: VacancySummary[];
  private currentDetails: VacancyFullDetails | null;
  private currentUser: User;
  private callbacks: VacancyViewCallbacks;
  private activeTab: 'pipeline' | 'activity' = 'pipeline';

  constructor(
    container: HTMLElement,
    vacancies: VacancySummary[],
    currentDetails: VacancyFullDetails | null,
    currentUser: User,
    callbacks: VacancyViewCallbacks
  ) {
    this.container = container;
    this.vacancies = vacancies;
    this.currentDetails = currentDetails;
    this.currentUser = currentUser;
    this.callbacks = callbacks;
  }

  public update(vacancies: VacancySummary[], currentDetails: VacancyFullDetails | null) {
    this.vacancies = vacancies;
    this.currentDetails = currentDetails;
    this.render();
  }

  public render() {
    if (!this.currentDetails) {
      this.container.innerHTML = `<div class="loading-state">Loading vacancy workspace...</div>`;
      return;
    }

    const v = this.currentDetails.vacancy;
    const candidates = this.currentDetails.candidates;
    const activity = this.currentDetails.activity;
    const u = this.currentUser;

    this.container.innerHTML = `
      <div class="workspace-layout">
        <!-- Vacancy Selector Tabs -->
        <nav class="vacancy-nav-tabs" aria-label="Vacancies">
          ${this.vacancies.map(vac => {
            const isSelected = vac.code === v.code;
            return `
              <button class="vacancy-tab-btn ${isSelected ? 'active' : ''}" data-code="${vac.code}">
                <div class="tab-top-row">
                  <span class="tab-role-title">${vac.title}</span>
                  <span class="tab-code-badge">${vac.code}</span>
                </div>
                <div class="tab-meta-row">
                  <span class="tab-team">${vac.team}</span>
                  <span class="tab-cand-count">${vac.candidate_count} applicants</span>
                  <span class="tab-avail-badge ${vac.available === 0 ? 'full' : ''}">${vac.available} open</span>
                </div>
              </button>
            `;
          }).join('')}
        </nav>

        <!-- Main Vacancy Area -->
        <main class="vacancy-main-content">
          <!-- Vacancy Header Card -->
          <div class="vacancy-header-card">
            <div class="vacancy-title-section">
              <div class="vacancy-badges">
                <span class="vacancy-code-tag">${v.code}</span>
                <span class="vacancy-team-tag">${v.team} Team</span>
                <span class="vacancy-revision-tag" title="Revision counter for optimistic concurrency">Rev ${v.revision}</span>
              </div>
              <h2 class="vacancy-main-title">${v.title}</h2>
            </div>

            <!-- Capacity Control -->
            <div class="vacancy-capacity-bar-card">
              <div class="cap-header">
                <span class="cap-title"><strong>Openings & Capacity:</strong> ${v.openings} Total</span>
                <span class="cap-status ${v.available > 0 ? 'has-openings' : 'no-openings'}">
                  ${v.available > 0 ? `${v.available} Opening(s) Available` : 'All Openings Committed'}
                </span>
              </div>
              <div class="segmented-capacity-bar" role="progressbar" aria-valuenow="${v.reserved + v.filled}" aria-valuemin="0" aria-valuemax="${v.openings}">
                <div class="seg seg-filled" style="width: ${(v.filled / Math.max(1, v.openings)) * 100}%;" title="${v.filled} Hired / Filled"></div>
                <div class="seg seg-reserved" style="width: ${(v.reserved / Math.max(1, v.openings)) * 100}%;" title="${v.reserved} Offer Reserved"></div>
                <div class="seg seg-available" style="width: ${(v.available / Math.max(1, v.openings)) * 100}%;" title="${v.available} Available"></div>
              </div>
              <div class="cap-legend">
                <span class="legend-item"><span class="dot dot-filled"></span> ${v.filled} Filled (Hired)</span>
                <span class="legend-item"><span class="dot dot-reserved"></span> ${v.reserved} Reserved (Offer)</span>
                <span class="legend-item"><span class="dot dot-available"></span> ${v.available} Available</span>
              </div>
            </div>

            <!-- Header Action Buttons -->
            <div class="vacancy-actions-row">
              ${u.role === 'coordinator' ? `
                <button id="add-candidate-btn" class="btn btn-primary" title="Add new candidate to this vacancy">
                  + Add Candidate
                </button>
              ` : ''}

              ${u.role === 'hiring manager' ? `
                <button id="batch-offers-btn" class="btn btn-secondary" title="Review and extend batch offers">
                  ⚡ Batch Offers
                </button>
              ` : ''}

              <button id="refresh-vacancy-btn" class="btn btn-outline btn-icon" title="Refresh latest state">
                ↻ Refresh
              </button>
            </div>
          </div>

          <!-- Funnel Chart Section -->
          <section class="vacancy-section funnel-section">
            <div class="section-header">
              <h3 class="section-title">Pipeline Funnel (D3)</h3>
              <span class="section-sub">Derived directly from candidate stage visit history</span>
            </div>
            <div id="funnel-container" class="funnel-container"></div>
          </section>

          <!-- Workspace View Tabs (Pipeline vs Activity) -->
          <div class="view-switch-tabs">
            <button class="view-tab-btn ${this.activeTab === 'pipeline' ? 'active' : ''}" id="tab-pipeline-btn">
              Candidates Pipeline (${candidates.length})
            </button>
            <button class="view-tab-btn ${this.activeTab === 'activity' ? 'active' : ''}" id="tab-activity-btn">
              Vacancy Activity Trail (${activity.length})
            </button>
          </div>

          <!-- Tab 1: Candidates Pipeline Board -->
          ${this.activeTab === 'pipeline' ? `
            <div class="pipeline-board">
              ${this.renderPipelineBoard(candidates)}
            </div>
          ` : `
            <!-- Tab 2: Activity Trail -->
            <div class="activity-trail-view">
              ${this.renderActivityTrail(activity)}
            </div>
          `}
        </main>
      </div>
    `;

    // Render D3 Funnel
    const funnelContainer = this.container.querySelector('#funnel-container') as HTMLElement;
    if (funnelContainer) {
      renderFunnel(funnelContainer, this.currentDetails.funnel);
    }

    this.bindEvents();
  }

  private renderPipelineBoard(candidates: Candidate[]): string {
    const activeStages: Stage[] = ['applied', 'screening', 'interview', 'offer', 'hired'];
    const terminalStages: Stage[] = ['rejected', 'withdrawn'];

    return `
      <div class="pipeline-stages-grid">
        ${activeStages.map(st => {
          const stageCands = candidates.filter(c => c.stage === st);
          return `
            <div class="pipeline-column stage-col-${st}">
              <div class="col-header">
                <span class="col-title">${st.toUpperCase()}</span>
                <span class="col-count">${stageCands.length}</span>
              </div>
              <div class="col-cards-list">
                ${stageCands.length === 0 ? `
                  <div class="col-empty-card">No candidates</div>
                ` : `
                  ${stageCands.map(c => this.renderCandidateCard(c)).join('')}
                `}
              </div>
            </div>
          `;
        }).join('')}

        <!-- Terminal Column -->
        <div class="pipeline-column stage-col-terminal">
          <div class="col-header">
            <span class="col-title">TERMINAL</span>
            <span class="col-count">${candidates.filter(c => terminalStages.includes(c.stage)).length}</span>
          </div>
          <div class="col-cards-list">
            ${candidates.filter(c => terminalStages.includes(c.stage)).map(c => this.renderCandidateCard(c)).join('')}
          </div>
        </div>
      </div>
    `;
  }

  private renderCandidateCard(c: Candidate): string {
    const isInterview = c.stage === 'interview';
    const isReady = c.offer_eligibility?.eligible;

    return `
      <div class="candidate-card ${c.is_terminal ? 'card-terminal' : ''}" data-cand-id="${c.id}" tabindex="0" role="button" aria-label="Candidate ${c.name}, ${c.stage}">
        <div class="card-top-row">
          <strong class="cand-name">${c.name}</strong>
          <span class="cand-id">${c.id}</span>
        </div>

        <div class="card-meta-row">
          <span class="cand-stage-pill stage-${c.stage}">${c.stage}</span>
          <span class="cand-version-pill">v${c.assessment_version}</span>
          <span class="cand-days">${c.days_since_applied}d</span>
        </div>

        ${isInterview ? `
          <div class="card-readiness-row">
            ${isReady ? `
              <span class="readiness-pill ready">✓ Offer Ready</span>
            ` : `
              <span class="readiness-pill blocked" title="${c.offer_eligibility?.reasons?.join('; ')}">⚠ Blocked</span>
            `}
            <span class="score-summary">
              ${c.current_scores.length}/${c.panel.length} scored
            </span>
          </div>
        ` : ''}

        ${c.panel.length > 0 ? `
          <div class="card-panel-row">
            <span class="panel-icon" aria-hidden="true">👥</span>
            <span class="panel-names">${c.panel.map(p => p.name.split(' ')[0]).join(', ')}</span>
          </div>
        ` : ''}

        ${c.notes.length > 0 ? `
          <div class="card-notes-count">
            💬 ${c.notes.length} note${c.notes.length === 1 ? '' : 's'}
          </div>
        ` : ''}
      </div>
    `;
  }

  private renderActivityTrail(activity: any[]): string {
    if (activity.length === 0) {
      return `<div class="empty-activity-box">No recorded activity for this vacancy yet.</div>`;
    }

    return `
      <div class="activity-table-wrapper">
        <table class="activity-table">
          <thead>
            <tr>
              <th>Time</th>
              <th>Action</th>
              <th>Description</th>
              <th>Actor</th>
            </tr>
          </thead>
          <tbody>
            ${activity.map(a => `
              <tr>
                <td class="cell-time">${new Date(a.created_at).toLocaleTimeString()}</td>
                <td class="cell-type"><span class="activity-badge badge-${a.action_type}">${a.action_type.replace('_', ' ')}</span></td>
                <td class="cell-desc">${a.description}</td>
                <td class="cell-actor">${a.actor_name}</td>
              </tr>
            `).join('')}
          </tbody>
        </table>
      </div>
    `;
  }

  private bindEvents() {
    // Vacancy nav tabs click
    const tabBtns = this.container.querySelectorAll('.vacancy-tab-btn');
    tabBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        const code = btn.getAttribute('data-code');
        if (code) this.callbacks.onSelectVacancy(code);
      });
    });

    // Add Candidate button
    const addCandBtn = this.container.querySelector('#add-candidate-btn');
    if (addCandBtn) {
      addCandBtn.addEventListener('click', () => {
        this.callbacks.onOpenAddCandidate();
      });
    }

    // Batch Offers button
    const batchBtn = this.container.querySelector('#batch-offers-btn');
    if (batchBtn) {
      batchBtn.addEventListener('click', () => {
        this.callbacks.onOpenBatchOffers();
      });
    }

    // Refresh button
    const refreshBtn = this.container.querySelector('#refresh-vacancy-btn');
    if (refreshBtn) {
      refreshBtn.addEventListener('click', () => {
        this.callbacks.onRefresh();
      });
    }

    // Candidate card click
    const candCards = this.container.querySelectorAll('.candidate-card');
    candCards.forEach(card => {
      const openCard = () => {
        const id = card.getAttribute('data-cand-id');
        if (!id || !this.currentDetails) return;
        const cand = this.currentDetails.candidates.find(c => c.id === id);
        if (cand) this.callbacks.onOpenCandidate(cand);
      };

      card.addEventListener('click', openCard);
      card.addEventListener('keydown', (e: Event) => {
        const keyEvent = e as KeyboardEvent;
        if (keyEvent.key === 'Enter' || keyEvent.key === ' ') {
          e.preventDefault();
          openCard();
        }
      });
    });

    // Tab Switchers (Pipeline vs Activity)
    const pipelineTabBtn = this.container.querySelector('#tab-pipeline-btn');
    if (pipelineTabBtn) {
      pipelineTabBtn.addEventListener('click', () => {
        this.activeTab = 'pipeline';
        this.render();
      });
    }
    const activityTabBtn = this.container.querySelector('#tab-activity-btn');
    if (activityTabBtn) {
      activityTabBtn.addEventListener('click', () => {
        this.activeTab = 'activity';
        this.render();
      });
    }
  }
}

import {
  User,
  VacancySummary,
  VacancyFullDetails,
  Candidate
} from './types';
import {
  fetchCurrentUser,
  fetchVacancies,
  fetchVacancyDetails,
  logout,
  ApiError
} from './api';
import { initTheme } from './theme';
import { renderHeader } from './components/header';
import { renderLogin } from './components/login';
import { VacancyView } from './components/vacancyView';
import { CandidateDrawer } from './components/candidateDrawer';
import { BatchOfferModal } from './components/batchOfferModal';
import { AddCandidateModal } from './components/addCandidateModal';

class App {
  private headerContainer: HTMLElement;
  private appContainer: HTMLElement;
  private drawerContainer: HTMLElement;
  private modalContainer: HTMLElement;
  private notificationContainer: HTMLElement;

  private currentUser: User | null = null;
  private vacancies: VacancySummary[] = [];
  private selectedVacancyCode: string = '';
  private currentVacancyDetails: VacancyFullDetails | null = null;
  private selectedCandidateId: string | null = null;

  private vacancyView: VacancyView | null = null;
  private candidateDrawer: CandidateDrawer | null = null;
  private batchOfferModal: BatchOfferModal | null = null;
  private addCandidateModal: AddCandidateModal | null = null;

  constructor() {
    this.headerContainer = document.getElementById('header-root')!;
    this.appContainer = document.getElementById('app-root')!;
    this.drawerContainer = document.getElementById('drawer-root')!;
    this.modalContainer = document.getElementById('modal-root')!;
    this.notificationContainer = document.getElementById('notification-root')!;

    this.candidateDrawer = new CandidateDrawer(this.drawerContainer, {
      onUpdated: (vacancy, candidate) => {
        this.currentVacancyDetails = vacancy;
        this.updateVacanciesSummary(vacancy.vacancy);
        this.selectedCandidateId = candidate.id;
        this.updateHash();
        this.renderWorkspace();
        if (this.candidateDrawer) {
          this.candidateDrawer.updateData(candidate, vacancy);
        }
        this.showToast('Candidate updated successfully', 'success');
      },
      onClose: () => {
        this.selectedCandidateId = null;
        this.updateHash();
      },
      onError: (err) => {
        this.handleError(err);
      }
    });

    window.addEventListener('hashchange', () => {
      this.readHash();
    });

    window.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        if (this.batchOfferModal) {
          this.batchOfferModal.close();
          this.batchOfferModal = null;
        } else if (this.addCandidateModal) {
          this.addCandidateModal.close();
          this.addCandidateModal = null;
        } else if (this.candidateDrawer) {
          this.candidateDrawer.close();
        }
      }
    });
  }

  public async init() {
    initTheme();
    try {
      this.currentUser = await fetchCurrentUser();
    } catch (e) {
      this.currentUser = null;
    }

    if (!this.currentUser) {
      this.renderLoginPage();
    } else {
      await this.loadWorkspace();
    }
  }

  private renderHeader() {
    renderHeader(this.headerContainer, this.currentUser, {
      onLogout: async () => {
        await logout();
        this.currentUser = null;
        this.currentVacancyDetails = null;
        this.selectedCandidateId = null;
        this.renderLoginPage();
      }
    });
  }

  private renderLoginPage() {
    this.renderHeader();
    this.drawerContainer.innerHTML = '';
    this.modalContainer.innerHTML = '';
    renderLogin(this.appContainer, {
      onLoginSuccess: async (user) => {
        this.currentUser = user;
        await this.loadWorkspace();
      }
    });
  }

  private async loadWorkspace() {
    this.renderHeader();
    this.appContainer.innerHTML = `<div class="loading-state">Loading workspace records...</div>`;

    try {
      this.vacancies = await fetchVacancies();
      if (this.vacancies.length === 0) {
        this.appContainer.innerHTML = `<div class="empty-state">No vacancies found.</div>`;
        return;
      }

      this.readHash();
      if (!this.selectedVacancyCode || !this.vacancies.some(v => v.code === this.selectedVacancyCode)) {
        this.selectedVacancyCode = this.vacancies[0].code;
      }

      await this.loadVacancy(this.selectedVacancyCode);
    } catch (err: any) {
      this.handleError(err);
    }
  }

  private async loadVacancy(code: string) {
    try {
      this.selectedVacancyCode = code;
      this.currentVacancyDetails = await fetchVacancyDetails(code);
      this.updateVacanciesSummary(this.currentVacancyDetails.vacancy);
      this.updateHash();
      this.renderWorkspace();

      // If candidate was selected in hash, open drawer
      if (this.selectedCandidateId) {
        const cand = this.currentVacancyDetails.candidates.find(c => c.id === this.selectedCandidateId);
        if (cand && this.candidateDrawer && this.currentUser) {
          this.candidateDrawer.show(cand, this.currentVacancyDetails, this.currentUser);
        }
      }
    } catch (err: any) {
      this.handleError(err);
    }
  }

  private renderWorkspace() {
    if (!this.currentUser || !this.currentVacancyDetails) return;

    if (!this.vacancyView) {
      this.vacancyView = new VacancyView(
        this.appContainer,
        this.vacancies,
        this.currentVacancyDetails,
        this.currentUser,
        {
          onSelectVacancy: (code) => {
            this.loadVacancy(code);
          },
          onOpenCandidate: (candidate) => {
            this.selectedCandidateId = candidate.id;
            this.updateHash();
            if (this.candidateDrawer && this.currentVacancyDetails && this.currentUser) {
              this.candidateDrawer.show(candidate, this.currentVacancyDetails, this.currentUser);
            }
          },
          onOpenAddCandidate: () => {
            this.openAddCandidateModal();
          },
          onOpenBatchOffers: () => {
            this.openBatchOffersModal();
          },
          onRefresh: () => {
            this.loadVacancy(this.selectedVacancyCode);
            this.showToast('Workspace refreshed', 'info');
          }
        }
      );
    } else {
      this.vacancyView.update(this.vacancies, this.currentVacancyDetails);
    }
  }

  private openAddCandidateModal() {
    if (!this.currentVacancyDetails) return;
    this.addCandidateModal = new AddCandidateModal(
      this.modalContainer,
      this.vacancies,
      this.selectedVacancyCode,
      this.currentVacancyDetails.vacancy.revision,
      {
        onCreated: (candidate, updatedVacancy) => {
          this.currentVacancyDetails = updatedVacancy;
          this.updateVacanciesSummary(updatedVacancy.vacancy);
          this.renderWorkspace();
          this.showToast(`Candidate ${candidate.name} (${candidate.id}) added!`, 'success');
          // Automatically open candidate drawer
          this.selectedCandidateId = candidate.id;
          this.updateHash();
          if (this.candidateDrawer && this.currentUser) {
            this.candidateDrawer.show(candidate, updatedVacancy, this.currentUser);
          }
        },
        onClose: () => {
          this.addCandidateModal = null;
        },
        onError: (err) => {
          this.handleError(err);
        }
      }
    );
    this.addCandidateModal.show();
  }

  private openBatchOffersModal() {
    if (!this.currentVacancyDetails) return;
    this.batchOfferModal = new BatchOfferModal(
      this.modalContainer,
      this.currentVacancyDetails,
      {
        onCompleted: (updatedVacancy) => {
          this.currentVacancyDetails = updatedVacancy;
          this.updateVacanciesSummary(updatedVacancy.vacancy);
          this.renderWorkspace();
          this.showToast('Batch offers successfully extended!', 'success');
        },
        onClose: () => {
          this.batchOfferModal = null;
        },
        onError: (err) => {
          this.handleError(err);
        }
      }
    );
    this.batchOfferModal.show();
  }

  private updateVacanciesSummary(summary: VacancySummary) {
    const idx = this.vacancies.findIndex(v => v.code === summary.code);
    if (idx !== -1) {
      this.vacancies[idx] = { ...this.vacancies[idx], ...summary };
    }
  }

  private updateHash() {
    const params = new URLSearchParams();
    if (this.selectedVacancyCode) {
      params.set('vacancy', this.selectedVacancyCode);
    }
    if (this.selectedCandidateId) {
      params.set('candidate', this.selectedCandidateId);
    }
    const hash = '#' + params.toString();
    if (window.location.hash !== hash) {
      history.replaceState(null, '', hash);
    }
  }

  private readHash() {
    const raw = window.location.hash.replace(/^#/, '');
    const params = new URLSearchParams(raw);
    const vCode = params.get('vacancy');
    const cId = params.get('candidate');
    if (vCode) {
      this.selectedVacancyCode = vCode;
    }
    this.selectedCandidateId = cId;
  }

  private handleError(err: ApiError | Error | any) {
    const message = err.message || 'An unexpected error occurred';
    if (err.status === 409) {
      this.showToast(`Concurrency Conflict: ${message}`, 'warning');
      // Refresh current vacancy state on conflict
      if (this.selectedVacancyCode) {
        this.loadVacancy(this.selectedVacancyCode);
      }
    } else if (err.status === 401) {
      this.showToast('Session expired. Please sign in again.', 'danger');
      this.currentUser = null;
      this.renderLoginPage();
    } else {
      this.showToast(message, 'danger');
    }
  }

  private showToast(message: string, type: 'success' | 'warning' | 'danger' | 'info' = 'info') {
    const toast = document.createElement('div');
    toast.className = `toast-notification toast-${type}`;
    toast.innerHTML = `
      <span class="toast-icon">${type === 'success' ? '✓' : type === 'warning' ? '⚠' : type === 'danger' ? '✖' : 'ℹ'}</span>
      <span class="toast-msg">${message}</span>
      <button class="toast-dismiss" aria-label="Dismiss">&times;</button>
    `;

    toast.querySelector('.toast-dismiss')?.addEventListener('click', () => {
      toast.remove();
    });

    this.notificationContainer.appendChild(toast);

    setTimeout(() => {
      toast.classList.add('fade-out');
      setTimeout(() => toast.remove(), 300);
    }, 4500);
  }
}

document.addEventListener('DOMContentLoaded', () => {
  const app = new App();
  app.init();
});

:root {
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --bg-primary: #f8fafc;
  --bg-surface: #ffffff;
  --bg-surface-elevated: #ffffff;
  --bg-surface-alt: #f1f5f9;
  --bg-card: #ffffff;
  --border-color: #e2e8f0;
  --border-subtle: #cbd5e1;
  --text-primary: #0f172a;
  --text-secondary: #475569;
  --text-muted: #64748b;
  --text-inverse: #ffffff;

  --primary-color: #2563eb;
  --primary-hover: #1d4ed8;
  --primary-subtle: #eff6ff;
  --primary-border: #bfdbfe;

  --success-color: #059669;
  --success-bg: #ecfdf5;
  --success-border: #a7f3d0;

  --warning-color: #d97706;
  --warning-bg: #fffbeb;
  --warning-border: #fde68a;

  --danger-color: #dc2626;
  --danger-bg: #fef2f2;
  --danger-border: #fecaca;

  /* Stage Colors */
  --stage-applied-bg: #e0f2fe;
  --stage-applied-color: #0369a1;
  --stage-screening-bg: #fef3c7;
  --stage-screening-color: #92400e;
  --stage-interview-bg: #ede9fe;
  --stage-interview-color: #5b21b6;
  --stage-offer-bg: #fce7f3;
  --stage-offer-color: #9d174d;
  --stage-hired-bg: #dcfce7;
  --stage-hired-color: #15803d;
  --stage-rejected-bg: #fee2e2;
  --stage-rejected-color: #991b1b;
  --stage-withdrawn-bg: #f1f5f9;
  --stage-withdrawn-color: #475569;

  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
  --shadow-xl: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04);

  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-full: 9999px;
}

[data-theme="dark"] {
  --bg-primary: #090d16;
  --bg-surface: #111827;
  --bg-surface-elevated: #1f2937;
  --bg-surface-alt: #1e293b;
  --bg-card: #131d2e;
  --border-color: #2e3c54;
  --border-subtle: #3b4b66;
  --text-primary: #f1f5f9;
  --text-secondary: #cbd5e1;
  --text-muted: #94a3b8;
  --text-inverse: #090d16;

  --primary-color: #3b82f6;
  --primary-hover: #60a5fa;
  --primary-subtle: #1e3a8a;
  --primary-border: #2563eb;

  --success-color: #10b981;
  --success-bg: #064e3b;
  --success-border: #047857;

  --warning-color: #f59e0b;
  --warning-bg: #78350f;
  --warning-border: #b45309;

  --danger-color: #ef4444;
  --danger-bg: #7f1d1d;
  --danger-border: #b91c1c;

  /* Dark Stage Colors */
  --stage-applied-bg: #0c4a6e;
  --stage-applied-color: #bae6fd;
  --stage-screening-bg: #713f12;
  --stage-screening-color: #fef08a;
  --stage-interview-bg: #4c1d95;
  --stage-interview-color: #ddd6fe;
  --stage-offer-bg: #701a75;
  --stage-offer-color: #fbcfe8;
  --stage-hired-bg: #14532d;
  --stage-hired-color: #bbf7d0;
  --stage-rejected-bg: #7f1d1d;
  --stage-rejected-color: #fecaca;
  --stage-withdrawn-bg: #334155;
  --stage-withdrawn-color: #e2e8f0;

  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.4);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.5);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.6);
}

/* Reset & Base Styles */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background-color: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  min-height: 100vh;
}

/* Focus visibility for accessibility */
*:focus-visible {
  outline: 2px solid var(--primary-color);
  outline-offset: 2px;
}

/* App Header */
.app-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0.75rem 1.5rem;
  background-color: var(--bg-surface);
  border-bottom: 1px solid var(--border-color);
  position: sticky;
  top: 0;
  z-index: 40;
  box-shadow: var(--shadow-sm);
}

.header-brand {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.brand-logo {
  color: var(--primary-color);
  display: flex;
  align-items: center;
}

.brand-title {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--text-primary);
  letter-spacing: -0.02em;
}

.brand-tagline {
  font-size: 0.75rem;
  color: var(--text-muted);
  display: block;
}

.header-controls {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.theme-toggle-btn {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  background: var(--bg-surface-alt);
  border: 1px solid var(--border-color);
  padding: 0.35rem 0.75rem;
  border-radius: var(--radius-full);
  cursor: pointer;
  color: var(--text-secondary);
  font-size: 0.85rem;
  font-weight: 500;
  transition: background 0.15s ease;
}

.theme-toggle-btn:hover {
  background: var(--border-color);
}

[data-theme="dark"] .light-icon { display: none; }
[data-theme="light"] .dark-icon { display: none; }
:root:not([data-theme="dark"]) .dark-icon { display: none; }

.user-profile-badge {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  background: var(--bg-surface-alt);
  padding: 0.25rem 0.75rem 0.25rem 0.35rem;
  border-radius: var(--radius-full);
  border: 1px solid var(--border-color);
}

.user-avatar {
  width: 28px;
  height: 28px;
  border-radius: var(--radius-full);
  background: var(--primary-color);
  color: #fff;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.85rem;
}

.user-info {
  display: flex;
  flex-direction: column;
}

.user-name {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text-primary);
  line-height: 1.1;
}

.user-role-tag {
  font-size: 0.68rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  color: var(--primary-color);
}

/* Workspace Layout */
.workspace-layout {
  display: flex;
  flex-direction: column;
  max-width: 1400px;
  margin: 0 auto;
  padding: 1.25rem;
  gap: 1.25rem;
}

/* Vacancy Nav Tabs */
.vacancy-nav-tabs {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 0.75rem;
}

.vacancy-tab-btn {
  background: var(--bg-surface);
  border: 2px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 0.85rem 1rem;
  text-align: left;
  cursor: pointer;
  transition: all 0.15s ease;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.vacancy-tab-btn:hover {
  border-color: var(--primary-border);
  background: var(--bg-surface-alt);
}

.vacancy-tab-btn.active {
  border-color: var(--primary-color);
  background: var(--primary-subtle);
  box-shadow: var(--shadow-sm);
}

.tab-top-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.tab-role-title {
  font-weight: 700;
  font-size: 1rem;
  color: var(--text-primary);
}

.tab-code-badge {
  font-size: 0.75rem;
  font-weight: 600;
  background: var(--bg-surface-alt);
  padding: 0.15rem 0.45rem;
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  border: 1px solid var(--border-color);
}

.tab-meta-row {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  font-size: 0.8rem;
  color: var(--text-muted);
}

.tab-avail-badge {
  margin-left: auto;
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--success-color);
}

.tab-avail-badge.full {
  color: var(--warning-color);
}

/* Vacancy Header Card */
.vacancy-header-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 1.25rem 1.5rem;
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: 1.25rem;
  box-shadow: var(--shadow-sm);
}

.vacancy-badges {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-bottom: 0.35rem;
}

.vacancy-code-tag, .vacancy-team-tag, .vacancy-revision-tag {
  font-size: 0.75rem;
  font-weight: 600;
  padding: 0.15rem 0.5rem;
  border-radius: var(--radius-sm);
}

.vacancy-code-tag {
  background: var(--primary-subtle);
  color: var(--primary-color);
  border: 1px solid var(--primary-border);
}

.vacancy-team-tag {
  background: var(--bg-surface-alt);
  color: var(--text-secondary);
  border: 1px solid var(--border-color);
}

.vacancy-revision-tag {
  background: var(--bg-surface-alt);
  color: var(--text-muted);
  border: 1px dashed var(--border-color);
}

.vacancy-main-title {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--text-primary);
  letter-spacing: -0.02em;
}

/* Capacity Bar Card */
.vacancy-capacity-bar-card {
  background: var(--bg-surface-alt);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 0.85rem 1.25rem;
  min-width: 320px;
  flex: 1;
  max-width: 480px;
}

.cap-header {
  display: flex;
  justify-content: space-between;
  font-size: 0.85rem;
  margin-bottom: 0.4rem;
}

.cap-status.has-openings {
  color: var(--success-color);
  font-weight: 700;
}

.cap-status.no-openings {
  color: var(--warning-color);
  font-weight: 700;
}

.segmented-capacity-bar {
  height: 12px;
  background: var(--border-color);
  border-radius: var(--radius-full);
  display: flex;
  overflow: hidden;
  margin-bottom: 0.4rem;
}

.seg-filled {
  background: var(--success-color);
}

.seg-reserved {
  background: #ec4899;
}

.seg-available {
  background: #3b82f6;
  opacity: 0.25;
}

.cap-legend {
  display: flex;
  gap: 0.85rem;
  font-size: 0.75rem;
  color: var(--text-secondary);
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 0.35rem;
}

.dot {
  width: 8px;
  height: 8px;
  border-radius: var(--radius-full);
  display: inline-block;
}

.dot-filled { background: var(--success-color); }
.dot-reserved { background: #ec4899; }
.dot-available { background: #93c5fd; }

.vacancy-actions-row {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  flex-wrap: wrap;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  padding: 0.55rem 1rem;
  border-radius: var(--radius-md);
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  border: 1px solid transparent;
  transition: all 0.15s ease;
  text-decoration: none;
  line-height: 1.2;
}

.btn:disabled, .btn.disabled-btn {
  opacity: 0.5;
  cursor: not-allowed;
  pointer-events: none;
}

.btn-primary {
  background: var(--primary-color);
  color: #fff;
}
.btn-primary:hover:not(:disabled) {
  background: var(--primary-hover);
}

.btn-secondary {
  background: #7c3aed;
  color: #fff;
}
.btn-secondary:hover:not(:disabled) {
  background: #6d28d9;
}

.btn-success {
  background: var(--success-color);
  color: #fff;
}
.btn-success:hover:not(:disabled) {
  background: #047857;
}

.btn-danger {
  background: var(--danger-color);
  color: #fff;
}
.btn-danger:hover:not(:disabled) {
  background: #b91c1c;
}

.btn-outline {
  background: transparent;
  border-color: var(--border-color);
  color: var(--text-primary);
}
.btn-outline:hover:not(:disabled) {
  background: var(--bg-surface-alt);
}

.btn-danger-outline {
  background: transparent;
  border-color: var(--danger-border);
  color: var(--danger-color);
}
.btn-danger-outline:hover:not(:disabled) {
  background: var(--danger-bg);
}

.btn-neutral-outline {
  background: transparent;
  border-color: var(--border-color);
  color: var(--text-secondary);
}
.btn-neutral-outline:hover:not(:disabled) {
  background: var(--bg-surface-alt);
}

.btn-sm {
  padding: 0.35rem 0.65rem;
  font-size: 0.8rem;
}

.btn-block {
  width: 100%;
}

/* Funnel Section */
.vacancy-section {
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 1.25rem 1.5rem;
  box-shadow: var(--shadow-sm);
}

.section-header {
  margin-bottom: 1rem;
}

.section-title {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--text-primary);
}

.section-sub {
  font-size: 0.8rem;
  color: var(--text-muted);
}

/* D3 Funnel Styles */
.funnel-container {
  width: 100%;
  overflow-x: auto;
}

.funnel-chart-wrapper {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.funnel-svg {
  width: 100%;
  height: auto;
  max-height: 260px;
}

.grid-lines line {
  stroke: var(--border-color);
  stroke-dasharray: 3, 3;
}

.funnel-bar-reached {
  fill: var(--primary-color);
  opacity: 0.85;
}

.funnel-bar-remain {
  fill: var(--success-color);
}

.stage-applied .funnel-bar-reached { fill: #0284c7; }
.stage-screening .funnel-bar-reached { fill: #d97706; }
.stage-interview .funnel-bar-reached { fill: #7c3aed; }
.stage-offer .funnel-bar-reached { fill: #db2777; }
.stage-hired .funnel-bar-reached { fill: #059669; }

.funnel-val-label {
  fill: var(--text-primary);
  font-size: 12px;
  font-weight: 700;
}

.x-axis text {
  fill: var(--text-secondary);
  font-size: 12px;
  font-weight: 600;
}

.funnel-metrics-row {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(130px, 1fr));
  gap: 0.75rem;
}

.funnel-stage-card {
  background: var(--bg-surface-alt);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 0.65rem;
}

.stage-card-header {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.8rem;
  font-weight: 700;
  margin-bottom: 0.4rem;
}

.stage-dot {
  width: 8px;
  height: 8px;
  border-radius: var(--radius-full);
}

.stage-dot.applied { background: #0284c7; }
.stage-dot.screening { background: #d97706; }
.stage-dot.interview { background: #7c3aed; }
.stage-dot.offer { background: #db2777; }
.stage-dot.hired { background: #059669; }

.stage-card-stats {
  display: flex;
  justify-content: space-between;
  font-size: 0.72rem;
}

.stat-item {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.stat-num {
  font-weight: 700;
  font-size: 0.95rem;
  color: var(--text-primary);
}

.stat-num.active-val { color: var(--success-color); }
.stat-num.lost-val { color: var(--danger-color); }

.stat-lbl {
  color: var(--text-muted);
  font-size: 0.68rem;
  text-transform: uppercase;
}

.funnel-empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 2.5rem 1.5rem;
  text-align: center;
  background: var(--bg-surface-alt);
  border: 2px dashed var(--border-color);
  border-radius: var(--radius-md);
}

.empty-state-icon {
  color: var(--text-muted);
  margin-bottom: 0.75rem;
}

.empty-state-text strong {
  font-size: 1.1rem;
  color: var(--text-primary);
  display: block;
  margin-bottom: 0.25rem;
}

.empty-state-text p {
  font-size: 0.85rem;
  color: var(--text-muted);
  max-width: 480px;
  margin-bottom: 1.25rem;
}

.funnel-empty-grid {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
  justify-content: center;
}

.funnel-empty-stage {
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  padding: 0.4rem 0.85rem;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.empty-stage-name {
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--text-secondary);
}

.empty-stage-val {
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--text-muted);
}

/* View Switch Tabs */
.view-switch-tabs {
  display: flex;
  gap: 0.5rem;
  border-bottom: 1px solid var(--border-color);
  padding-bottom: 0.25rem;
}

.view-tab-btn {
  background: transparent;
  border: none;
  border-bottom: 3px solid transparent;
  padding: 0.5rem 1rem;
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text-secondary);
  cursor: pointer;
  transition: all 0.15s ease;
}

.view-tab-btn:hover {
  color: var(--text-primary);
}

.view-tab-btn.active {
  color: var(--primary-color);
  border-bottom-color: var(--primary-color);
}

/* Pipeline Board Grid */
.pipeline-stages-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 1rem;
  align-items: start;
}

.pipeline-column {
  background: var(--bg-surface-alt);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 0.75rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  min-height: 240px;
}

.col-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--text-secondary);
  padding: 0.25rem 0.35rem;
  border-bottom: 2px solid var(--border-color);
}

.col-count {
  background: var(--border-color);
  padding: 0.1rem 0.45rem;
  border-radius: var(--radius-full);
  font-size: 0.75rem;
  color: var(--text-primary);
}

.col-cards-list {
  display: flex;
  flex-direction: column;
  gap: 0.65rem;
}

.col-empty-card {
  font-size: 0.8rem;
  color: var(--text-muted);
  text-align: center;
  padding: 1.5rem 0.5rem;
  border: 1px dashed var(--border-subtle);
  border-radius: var(--radius-sm);
}

/* Candidate Card */
.candidate-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 0.85rem;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
  box-shadow: var(--shadow-sm);
  transition: all 0.15s ease;
}

.candidate-card:hover {
  border-color: var(--primary-border);
  box-shadow: var(--shadow-md);
  transform: translateY(-1px);
}

.candidate-card:focus-visible {
  outline: 2px solid var(--primary-color);
}

.card-top-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
}

.cand-name {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--text-primary);
}

.cand-id {
  font-size: 0.75rem;
  color: var(--text-muted);
  font-family: monospace;
}

.card-meta-row {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.75rem;
}

.cand-stage-pill {
  padding: 0.1rem 0.45rem;
  border-radius: var(--radius-sm);
  font-weight: 600;
  text-transform: capitalize;
}

.cand-stage-pill.stage-applied { background: var(--stage-applied-bg); color: var(--stage-applied-color); }
.cand-stage-pill.stage-screening { background: var(--stage-screening-bg); color: var(--stage-screening-color); }
.cand-stage-pill.stage-interview { background: var(--stage-interview-bg); color: var(--stage-interview-color); }
.cand-stage-pill.stage-offer { background: var(--stage-offer-bg); color: var(--stage-offer-color); }
.cand-stage-pill.stage-hired { background: var(--stage-hired-bg); color: var(--stage-hired-color); }
.cand-stage-pill.stage-rejected { background: var(--stage-rejected-bg); color: var(--stage-rejected-color); }
.cand-stage-pill.stage-withdrawn { background: var(--stage-withdrawn-bg); color: var(--stage-withdrawn-color); }

.cand-version-pill {
  background: var(--bg-surface-alt);
  border: 1px solid var(--border-color);
  padding: 0.1rem 0.35rem;
  border-radius: var(--radius-sm);
  color: var(--text-muted);
}

.cand-days {
  color: var(--text-muted);
  margin-left: auto;
}

.card-readiness-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.75rem;
  background: var(--bg-surface-alt);
  padding: 0.25rem 0.45rem;
  border-radius: var(--radius-sm);
}

.readiness-pill.ready {
  color: var(--success-color);
  font-weight: 700;
}

.readiness-pill.blocked {
  color: var(--warning-color);
  font-weight: 700;
}

.score-summary {
  color: var(--text-secondary);
  font-size: 0.72rem;
}

.card-panel-row {
  font-size: 0.75rem;
  color: var(--text-secondary);
  display: flex;
  align-items: center;
  gap: 0.35rem;
}

.card-notes-count {
  font-size: 0.72rem;
  color: var(--text-muted);
}

/* Candidate Drawer */
.drawer-root.open {
  display: block;
}

.drawer-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.45);
  backdrop-filter: blur(2px);
  z-index: 50;
}

.drawer-content {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  width: 100%;
  max-width: 580px;
  background: var(--bg-surface);
  border-left: 1px solid var(--border-color);
  z-index: 60;
  display: flex;
  flex-direction: column;
  box-shadow: var(--shadow-xl);
  overflow: hidden;
}

.drawer-header {
  padding: 1.25rem 1.5rem;
  border-bottom: 1px solid var(--border-color);
  background: var(--bg-surface-elevated);
  position: relative;
}

.drawer-header-meta {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 0.4rem;
}

.cand-id-badge {
  font-family: monospace;
  font-size: 0.8rem;
  background: var(--bg-surface-alt);
  padding: 0.15rem 0.45rem;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-color);
}

.cand-stage-badge {
  font-size: 0.75rem;
  font-weight: 700;
  padding: 0.15rem 0.5rem;
  border-radius: var(--radius-sm);
}

.cand-version-badge {
  font-size: 0.75rem;
  background: var(--primary-subtle);
  color: var(--primary-color);
  padding: 0.15rem 0.45rem;
  border-radius: var(--radius-sm);
  font-weight: 600;
}

.drawer-title {
  font-size: 1.4rem;
  font-weight: 800;
  color: var(--text-primary);
  margin-bottom: 0.25rem;
}

.drawer-subtitle {
  font-size: 0.85rem;
  color: var(--text-muted);
  display: flex;
  gap: 0.5rem;
  align-items: center;
}

.drawer-close-btn {
  position: absolute;
  top: 1.25rem;
  right: 1.5rem;
  background: transparent;
  border: none;
  font-size: 1.6rem;
  color: var(--text-muted);
  cursor: pointer;
  line-height: 1;
}

.drawer-close-btn:hover {
  color: var(--text-primary);
}

.drawer-body {
  padding: 1.5rem;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.drawer-section {
  background: var(--bg-surface-alt);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 1rem 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.section-heading {
  font-size: 1rem;
  font-weight: 700;
  color: var(--text-primary);
}

.section-heading-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.section-hint {
  font-size: 0.8rem;
  color: var(--text-muted);
  line-height: 1.4;
}

.version-tag {
  font-size: 0.75rem;
  font-weight: 700;
  background: var(--primary-subtle);
  color: var(--primary-color);
  padding: 0.2rem 0.5rem;
  border-radius: var(--radius-full);
}

/* Stage Stepper */
.stage-stepper {
  display: flex;
  justify-content: space-between;
  position: relative;
  margin-top: 0.5rem;
}

.step-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.25rem;
  z-index: 2;
}

.step-circle {
  width: 24px;
  height: 24px;
  border-radius: var(--radius-full);
  background: var(--bg-surface);
  border: 2px solid var(--border-subtle);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--text-muted);
}

.step-item.visited .step-circle {
  background: var(--primary-color);
  border-color: var(--primary-color);
  color: #fff;
}

.step-item.current .step-circle {
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px var(--primary-subtle);
}

.step-name {
  font-size: 0.72rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: capitalize;
}

.step-item.current .step-name {
  color: var(--primary-color);
  font-weight: 700;
}

/* Offer Readiness Card */
.offer-readiness-card {
  border-width: 2px;
}

.offer-readiness-card.ready {
  border-color: var(--success-border);
  background: var(--success-bg);
}

.offer-readiness-card.blocked {
  border-color: var(--warning-border);
  background: var(--warning-bg);
}

.readiness-header {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.readiness-badge {
  font-size: 0.8rem;
  font-weight: 800;
  padding: 0.25rem 0.6rem;
  border-radius: var(--radius-sm);
}

.badge-ready {
  background: var(--success-color);
  color: #fff;
}

.badge-blocked {
  background: var(--warning-color);
  color: #fff;
}

.readiness-summary {
  font-size: 0.85rem;
  color: var(--text-primary);
  font-weight: 600;
}

.blocked-reasons-list {
  margin-left: 1.25rem;
  font-size: 0.82rem;
  color: var(--text-secondary);
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
}

/* Action buttons group */
.action-buttons-group {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.role-notice {
  font-size: 0.82rem;
  color: var(--text-muted);
  background: var(--bg-surface);
  padding: 0.5rem 0.75rem;
  border-radius: var(--radius-sm);
  border: 1px dashed var(--border-color);
}

.frozen-banner {
  background: var(--bg-surface);
  padding: 0.5rem 0.75rem;
  border-radius: var(--radius-sm);
  font-size: 0.82rem;
  color: var(--text-muted);
  border: 1px solid var(--border-color);
}

/* Score Cards */
.scores-list {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.score-card {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: var(--bg-surface);
  padding: 0.6rem 0.85rem;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-color);
}

.score-card-member {
  display: flex;
  flex-direction: column;
}

.member-email {
  font-size: 0.75rem;
  color: var(--text-muted);
}

.score-badge {
  font-size: 0.82rem;
  font-weight: 700;
  padding: 0.2rem 0.5rem;
  border-radius: var(--radius-sm);
}

.score-badge.val-5, .score-badge.val-4 {
  background: var(--success-bg);
  color: var(--success-color);
  border: 1px solid var(--success-border);
}

.score-badge.val-3 {
  background: var(--warning-bg);
  color: var(--warning-color);
  border: 1px solid var(--warning-border);
}

.score-badge.val-2, .score-badge.val-1 {
  background: var(--danger-bg);
  color: var(--danger-color);
  border: 1px solid var(--danger-border);
}

.score-badge.val-pending {
  background: var(--bg-surface-alt);
  color: var(--text-muted);
  border: 1px dashed var(--border-subtle);
}

.submit-score-box {
  background: var(--bg-surface);
  border: 1px solid var(--primary-border);
  border-radius: var(--radius-sm);
  padding: 0.75rem;
  margin-top: 0.75rem;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.score-input-row {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.score-radios {
  display: flex;
  gap: 0.4rem;
}

.score-radio-label {
  width: 32px;
  height: 32px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  font-weight: 700;
  font-size: 0.9rem;
  background: var(--bg-surface-alt);
}

.score-radio-label input {
  display: none;
}

.score-radio-label.selected, .score-radio-label:has(input:checked) {
  background: var(--primary-color);
  color: #fff;
  border-color: var(--primary-color);
}

/* Historical Scores */
.historical-scores-section {
  margin-top: 0.85rem;
  border-top: 1px dashed var(--border-color);
  padding-top: 0.75rem;
}

.sub-heading {
  font-size: 0.88rem;
  font-weight: 700;
  color: var(--text-secondary);
  margin-bottom: 0.4rem;
}

.historical-scores-list {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.historical-score-item {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  font-size: 0.8rem;
  background: var(--bg-surface);
  padding: 0.4rem 0.65rem;
  border-radius: var(--radius-sm);
  color: var(--text-muted);
}

.hist-version {
  font-weight: 600;
  color: var(--text-secondary);
}

.hist-tag {
  margin-left: auto;
  font-size: 0.7rem;
  background: var(--bg-surface-alt);
  padding: 0.1rem 0.35rem;
  border-radius: var(--radius-sm);
}

/* Panel Section */
.panel-members-list {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.panel-member-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: var(--bg-surface);
  padding: 0.5rem 0.75rem;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-color);
}

.member-info {
  display: flex;
  flex-direction: column;
}

.member-name {
  font-weight: 600;
  font-size: 0.85rem;
}

.add-panel-box {
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  padding: 0.75rem;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.add-panel-controls {
  display: flex;
  gap: 0.5rem;
}

.form-select, .form-input, .form-textarea {
  width: 100%;
  padding: 0.45rem 0.65rem;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  background: var(--bg-surface);
  color: var(--text-primary);
  font-family: inherit;
  font-size: 0.85rem;
}

.form-select:focus, .form-input:focus, .form-textarea:focus {
  border-color: var(--primary-color);
  outline: none;
}

/* Notes Section */
.notes-list {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  max-height: 200px;
  overflow-y: auto;
}

.note-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  padding: 0.6rem 0.75rem;
}

.note-meta {
  display: flex;
  justify-content: space-between;
  font-size: 0.75rem;
  color: var(--text-muted);
  margin-bottom: 0.25rem;
}

.note-text {
  font-size: 0.85rem;
  color: var(--text-primary);
}

.add-note-box {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

/* Modal Dialogs */
.modal-root.open {
  display: block;
}

.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.55);
  backdrop-filter: blur(2px);
  z-index: 70;
}

.modal-dialog {
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 90%;
  max-width: 680px;
  max-height: 85vh;
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  z-index: 80;
  box-shadow: var(--shadow-xl);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.modal-header {
  padding: 1.25rem 1.5rem;
  border-bottom: 1px solid var(--border-color);
  background: var(--bg-surface-elevated);
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.modal-title {
  font-size: 1.25rem;
  font-weight: 800;
  color: var(--text-primary);
}

.modal-subtitle {
  font-size: 0.8rem;
  color: var(--text-muted);
}

.modal-close-btn {
  background: transparent;
  border: none;
  font-size: 1.5rem;
  color: var(--text-muted);
  cursor: pointer;
}

.modal-body {
  padding: 1.5rem;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.modal-footer {
  display: flex;
  justify-content: flex-end;
  gap: 0.75rem;
  margin-top: 1rem;
}

.center-footer {
  justify-content: center;
}

/* Batch Modal Specifics */
.batch-capacity-preview {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: var(--bg-surface-alt);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 0.85rem 1.25rem;
}

.capacity-box {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
}

.cap-lbl {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
}

.cap-val {
  font-size: 1.1rem;
  font-weight: 800;
  color: var(--text-primary);
}

.cap-breakdown {
  font-size: 0.75rem;
  color: var(--text-secondary);
}

.available-txt {
  color: var(--success-color);
}

.overbooked-txt {
  color: var(--danger-color);
}

.batch-candidate-checklist {
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
  max-height: 280px;
  overflow-y: auto;
}

.batch-cand-row {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 0.75rem;
  cursor: pointer;
  transition: all 0.15s ease;
}

.batch-cand-row:hover {
  background: var(--bg-surface-alt);
  border-color: var(--primary-border);
}

.batch-cand-row.checked {
  border-color: var(--primary-color);
  background: var(--primary-subtle);
}

.batch-cand-row.ineligible-row {
  border-left: 4px solid var(--warning-color);
}

.batch-cand-info {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  flex: 1;
}

.cand-name-row {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.cand-details-row {
  font-size: 0.75rem;
  color: var(--text-muted);
}

.ineligible-reasons-inline {
  font-size: 0.75rem;
  color: var(--warning-color);
  font-weight: 600;
}

.eligible-badge-inline {
  font-size: 0.75rem;
  color: var(--success-color);
  font-weight: 600;
}

.review-summary-card {
  border: 2px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 1rem 1.25rem;
}

.review-summary-card.ready {
  border-color: var(--success-border);
  background: var(--success-bg);
}

.review-summary-card.blocked {
  border-color: var(--warning-border);
  background: var(--warning-bg);
}

.capacity-review-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.75rem;
  margin: 0.85rem 0;
  text-align: center;
}

.cap-review-item {
  background: var(--bg-surface);
  padding: 0.5rem;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-color);
}

.rev-lbl {
  font-size: 0.72rem;
  color: var(--text-muted);
  display: block;
}

.rev-val {
  font-size: 1.15rem;
  font-weight: 800;
  color: var(--text-primary);
}

.batch-blockers-box {
  background: var(--bg-surface);
  padding: 0.75rem;
  border-radius: var(--radius-sm);
  border: 1px solid var(--warning-border);
  font-size: 0.82rem;
  color: var(--warning-color);
}

.batch-blockers-box ul {
  margin-left: 1.25rem;
  margin-top: 0.25rem;
}

.batch-guarantee-note {
  font-size: 0.82rem;
  color: var(--text-secondary);
}

.review-candidates-list {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  max-height: 200px;
  overflow-y: auto;
}

.review-cand-item {
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  padding: 0.5rem 0.75rem;
}

.cand-item-header {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.85rem;
}

.cand-elig-badge {
  margin-left: auto;
  font-size: 0.72rem;
  font-weight: 700;
  padding: 0.1rem 0.4rem;
  border-radius: var(--radius-sm);
}

.cand-elig-badge.elig-yes {
  background: var(--success-bg);
  color: var(--success-color);
}

.cand-elig-badge.elig-no {
  background: var(--warning-bg);
  color: var(--warning-color);
}

.cand-reasons-box {
  font-size: 0.75rem;
  color: var(--danger-color);
  margin-top: 0.25rem;
}

.batch-id-txt {
  word-break: break-all;
  font-family: monospace;
}

/* Success step */
.success-step {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: 1.5rem 0;
}

.success-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-full);
  background: var(--success-color);
  color: #fff;
  font-size: 1.75rem;
  font-weight: 800;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 0.75rem;
}

.batch-receipt-card {
  background: var(--bg-surface-alt);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 1rem 1.5rem;
  width: 100%;
  max-width: 440px;
  margin: 1.25rem 0;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  text-align: left;
}

.receipt-row {
  display: flex;
  justify-content: space-between;
  font-size: 0.85rem;
}

.receipt-lbl {
  color: var(--text-muted);
}

.receipt-val {
  font-weight: 700;
  color: var(--text-primary);
}

/* Login Page */
.login-page {
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 3rem 1rem;
  min-height: calc(100vh - 100px);
}

.login-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 2rem;
  max-width: 460px;
  width: 100%;
  box-shadow: var(--shadow-lg);
}

.login-header {
  text-align: center;
  margin-bottom: 1.5rem;
}

.login-brand-icon {
  color: var(--primary-color);
  margin-bottom: 0.5rem;
}

.login-title {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--text-primary);
}

.login-desc {
  font-size: 0.85rem;
  color: var(--text-muted);
}

.demo-accounts-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.75rem;
  margin-bottom: 1.5rem;
}

.demo-account-btn {
  background: var(--bg-surface-alt);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 0.75rem;
  text-align: left;
  cursor: pointer;
  transition: all 0.15s ease;
}

.demo-account-btn:hover {
  background: var(--primary-subtle);
  border-color: var(--primary-border);
  transform: translateY(-1px);
}

.demo-name {
  font-weight: 700;
  font-size: 0.9rem;
  color: var(--text-primary);
}

.demo-role {
  font-size: 0.72rem;
  font-weight: 600;
  text-transform: uppercase;
}

.demo-role.role-hiring-manager { color: #db2777; }
.demo-role.role-coordinator { color: #0284c7; }
.demo-role.role-panel { color: #7c3aed; }

.demo-email {
  font-size: 0.7rem;
  color: var(--text-muted);
  margin-top: 0.2rem;
}

.login-divider {
  display: flex;
  align-items: center;
  text-align: center;
  margin: 1.25rem 0;
  color: var(--text-muted);
  font-size: 0.8rem;
}

.login-divider::before, .login-divider::after {
  content: '';
  flex: 1;
  border-bottom: 1px solid var(--border-color);
}

.login-divider span {
  padding: 0 0.75rem;
}

.manual-login-form {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.form-group label {
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--text-secondary);
}

.login-error-box {
  background: var(--danger-bg);
  border: 1px solid var(--danger-border);
  color: var(--danger-color);
  padding: 0.65rem 0.85rem;
  border-radius: var(--radius-sm);
  font-size: 0.82rem;
  margin-bottom: 1rem;
}

/* Activity Table */
.activity-table-wrapper {
  overflow-x: auto;
}

.activity-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.85rem;
}

.activity-table th {
  text-align: left;
  padding: 0.65rem;
  border-bottom: 2px solid var(--border-color);
  color: var(--text-secondary);
  font-size: 0.75rem;
  text-transform: uppercase;
}

.activity-table td {
  padding: 0.65rem;
  border-bottom: 1px solid var(--border-color);
}

.activity-badge {
  font-size: 0.72rem;
  font-weight: 700;
  padding: 0.15rem 0.45rem;
  border-radius: var(--radius-sm);
  background: var(--bg-surface-alt);
  color: var(--text-secondary);
}

/* Toast Notifications */
.notification-container {
  position: fixed;
  bottom: 1.5rem;
  right: 1.5rem;
  z-index: 100;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  max-width: 400px;
}

.toast-notification {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  padding: 0.75rem 1rem;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  font-size: 0.85rem;
  font-weight: 600;
  color: #fff;
  transition: opacity 0.3s ease;
}

.toast-success { background: #059669; }
.toast-warning { background: #d97706; }
.toast-danger { background: #dc2626; }
.toast-info { background: #2563eb; }

.toast-notification.fade-out {
  opacity: 0;
}

.toast-dismiss {
  background: transparent;
  border: none;
  color: #fff;
  font-size: 1.2rem;
  margin-left: auto;
  cursor: pointer;
  line-height: 1;
}

/* Reduced Motion */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/* Mobile & Narrow screen responsiveness */
@media (max-width: 768px) {
  .app-header {
    padding: 0.5rem 1rem;
  }

  .workspace-layout {
    padding: 0.75rem;
    gap: 0.85rem;
  }

  .vacancy-header-card {
    flex-direction: column;
    align-items: stretch;
    padding: 1rem;
  }

  .vacancy-capacity-bar-card {
    min-width: 100%;
    max-width: 100%;
  }

  .pipeline-stages-grid {
    grid-template-columns: 1fr;
  }

  .drawer-content {
    max-width: 100%;
  }

  .demo-accounts-grid {
    grid-template-columns: 1fr;
  }
}

:root {
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --bg-primary: #f8fafc;
  --bg-surface: #ffffff;
  --bg-surface-elevated: #ffffff;
  --bg-surface-alt: #f1f5f9;
  --bg-card: #ffffff;
  --border-color: #e2e8f0;
  --border-subtle: #cbd5e1;
  --text-primary: #0f172a;
  --text-secondary: #475569;
  --text-muted: #64748b;
  --text-inverse: #ffffff;

  --primary-color: #2563eb;
  --primary-hover: #1d4ed8;
  --primary-subtle: #eff6ff;
  --primary-border: #bfdbfe;

  --success-color: #059669;
  --success-bg: #ecfdf5;
  --success-border: #a7f3d0;

  --warning-color: #d97706;
  --warning-bg: #fffbeb;
  --warning-border: #fde68a;

  --danger-color: #dc2626;
  --danger-bg: #fef2f2;
  --danger-border: #fecaca;

  /* Stage Colors */
  --stage-applied-bg: #e0f2fe;
  --stage-applied-color: #0369a1;
  --stage-screening-bg: #fef3c7;
  --stage-screening-color: #92400e;
  --stage-interview-bg: #ede9fe;
  --stage-interview-color: #5b21b6;
  --stage-offer-bg: #fce7f3;
  --stage-offer-color: #9d174d;
  --stage-hired-bg: #dcfce7;
  --stage-hired-color: #15803d;
  --stage-rejected-bg: #fee2e2;
  --stage-rejected-color: #991b1b;
  --stage-withdrawn-bg: #f1f5f9;
  --stage-withdrawn-color: #475569;

  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
  --shadow-xl: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04);

  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-full: 9999px;
}

[data-theme="dark"] {
  --bg-primary: #090d16;
  --bg-surface: #111827;
  --bg-surface-elevated: #1f2937;
  --bg-surface-alt: #1e293b;
  --bg-card: #131d2e;
  --border-color: #2e3c54;
  --border-subtle: #3b4b66;
  --text-primary: #f1f5f9;
  --text-secondary: #cbd5e1;
  --text-muted: #94a3b8;
  --text-inverse: #090d16;

  --primary-color: #3b82f6;
  --primary-hover: #60a5fa;
  --primary-subtle: #1e3a8a;
  --primary-border: #2563eb;

  --success-color: #10b981;
  --success-bg: #064e3b;
  --success-border: #047857;

  --warning-color: #f59e0b;
  --warning-bg: #78350f;
  --warning-border: #b45309;

  --danger-color: #ef4444;
  --danger-bg: #7f1d1d;
  --danger-border: #b91c1c;

  /* Dark Stage Colors */
  --stage-applied-bg: #0c4a6e;
  --stage-applied-color: #bae6fd;
  --stage-screening-bg: #713f12;
  --stage-screening-color: #fef08a;
  --stage-interview-bg: #4c1d95;
  --stage-interview-color: #ddd6fe;
  --stage-offer-bg: #701a75;
  --stage-offer-color: #fbcfe8;
  --stage-hired-bg: #14532d;
  --stage-hired-color: #bbf7d0;
  --stage-rejected-bg: #7f1d1d;
  --stage-rejected-color: #fecaca;
  --stage-withdrawn-bg: #334155;
  --stage-withdrawn-color: #e2e8f0;

  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.4);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.5);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.6);
}

/* Reset & Base Styles */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background-color: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  min-height: 100vh;
}

/* Focus visibility for accessibility */
*:focus-visible {
  outline: 2px solid var(--primary-color);
  outline-offset: 2px;
}

/* App Header */
.app-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0.75rem 1.5rem;
  background-color: var(--bg-surface);
  border-bottom: 1px solid var(--border-color);
  position: sticky;
  top: 0;
  z-index: 40;
  box-shadow: var(--shadow-sm);
}

.header-brand {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.brand-logo {
  color: var(--primary-color);
  display: flex;
  align-items: center;
}

.brand-title {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--text-primary);
  letter-spacing: -0.02em;
}

.brand-tagline {
  font-size: 0.75rem;
  color: var(--text-muted);
  display: block;
}

.header-controls {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.theme-toggle-btn {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  background: var(--bg-surface-alt);
  border: 1px solid var(--border-color);
  padding: 0.35rem 0.75rem;
  border-radius: var(--radius-full);
  cursor: pointer;
  color: var(--text-secondary);
  font-size: 0.85rem;
  font-weight: 500;
  transition: background 0.15s ease;
}

.theme-toggle-btn:hover {
  background: var(--border-color);
}

[data-theme="dark"] .light-icon { display: none; }
[data-theme="light"] .dark-icon { display: none; }
:root:not([data-theme="dark"]) .dark-icon { display: none; }

.user-profile-badge {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  background: var(--bg-surface-alt);
  padding: 0.25rem 0.75rem 0.25rem 0.35rem;
  border-radius: var(--radius-full);
  border: 1px solid var(--border-color);
}

.user-avatar {
  width: 28px;
  height: 28px;
  border-radius: var(--radius-full);
  background: var(--primary-color);
  color: #fff;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.85rem;
}

.user-info {
  display: flex;
  flex-direction: column;
}

.user-name {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text-primary);
  line-height: 1.1;
}

.user-role-tag {
  font-size: 0.68rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  color: var(--primary-color);
}

/* Workspace Layout */
.workspace-layout {
  display: flex;
  flex-direction: column;
  max-width: 1400px;
  margin: 0 auto;
  padding: 1.25rem;
  gap: 1.25rem;
}

/* Vacancy Nav Tabs */
.vacancy-nav-tabs {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 0.75rem;
}

.vacancy-tab-btn {
  background: var(--bg-surface);
  border: 2px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 0.85rem 1rem;
  text-align: left;
  cursor: pointer;
  transition: all 0.15s ease;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.vacancy-tab-btn:hover {
  border-color: var(--primary-border);
  background: var(--bg-surface-alt);
}

.vacancy-tab-btn.active {
  border-color: var(--primary-color);
  background: var(--primary-subtle);
  box-shadow: var(--shadow-sm);
}

.tab-top-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.tab-role-title {
  font-weight: 700;
  font-size: 1rem;
  color: var(--text-primary);
}

.tab-code-badge {
  font-size: 0.75rem;
  font-weight: 600;
  background: var(--bg-surface-alt);
  padding: 0.15rem 0.45rem;
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  border: 1px solid var(--border-color);
}

.tab-meta-row {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  font-size: 0.8rem;
  color: var(--text-muted);
}

.tab-avail-badge {
  margin-left: auto;
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--success-color);
}

.tab-avail-badge.full {
  color: var(--warning-color);
}

/* Vacancy Header Card */
.vacancy-header-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 1.25rem 1.5rem;
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: 1.25rem;
  box-shadow: var(--shadow-sm);
}

.vacancy-badges {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-bottom: 0.35rem;
}

.vacancy-code-tag, .vacancy-team-tag, .vacancy-revision-tag {
  font-size: 0.75rem;
  font-weight: 600;
  padding: 0.15rem 0.5rem;
  border-radius: var(--radius-sm);
}

.vacancy-code-tag {
  background: var(--primary-subtle);
  color: var(--primary-color);
  border: 1px solid var(--primary-border);
}

.vacancy-team-tag {
  background: var(--bg-surface-alt);
  color: var(--text-secondary);
  border: 1px solid var(--border-color);
}

.vacancy-revision-tag {
  background: var(--bg-surface-alt);
  color: var(--text-muted);
  border: 1px dashed var(--border-color);
}

.vacancy-main-title {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--text-primary);
  letter-spacing: -0.02em;
}

/* Capacity Bar Card */
.vacancy-capacity-bar-card {
  background: var(--bg-surface-alt);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 0.85rem 1.25rem;
  min-width: 320px;
  flex: 1;
  max-width: 480px;
}

.cap-header {
  display: flex;
  justify-content: space-between;
  font-size: 0.85rem;
  margin-bottom: 0.4rem;
}

.cap-status.has-openings {
  color: var(--success-color);
  font-weight: 700;
}

.cap-status.no-openings {
  color: var(--warning-color);
  font-weight: 700;
}

.segmented-capacity-bar {
  height: 12px;
  background: var(--border-color);
  border-radius: var(--radius-full);
  display: flex;
  overflow: hidden;
  margin-bottom: 0.4rem;
}

.seg-filled {
  background: var(--success-color);
}

.seg-reserved {
  background: #ec4899;
}

.seg-available {
  background: #3b82f6;
  opacity: 0.25;
}

.cap-legend {
  display: flex;
  gap: 0.85rem;
  font-size: 0.75rem;
  color: var(--text-secondary);
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 0.35rem;
}

.dot {
  width: 8px;
  height: 8px;
  border-radius: var(--radius-full);
  display: inline-block;
}

.dot-filled { background: var(--success-color); }
.dot-reserved { background: #ec4899; }
.dot-available { background: #93c5fd; }

.vacancy-actions-row {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  flex-wrap: wrap;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  padding: 0.55rem 1rem;
  border-radius: var(--radius-md);
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  border: 1px solid transparent;
  transition: all 0.15s ease;
  text-decoration: none;
  line-height: 1.2;
}

.btn:disabled, .btn.disabled-btn {
  opacity: 0.5;
  cursor: not-allowed;
  pointer-events: none;
}

.btn-primary {
  background: var(--primary-color);
  color: #fff;
}
.btn-primary:hover:not(:disabled) {
  background: var(--primary-hover);
}

.btn-secondary {
  background: #7c3aed;
  color: #fff;
}
.btn-secondary:hover:not(:disabled) {
  background: #6d28d9;
}

.btn-success {
  background: var(--success-color);
  color: #fff;
}
.btn-success:hover:not(:disabled) {
  background: #047857;
}

.btn-danger {
  background: var(--danger-color);
  color: #fff;
}
.btn-danger:hover:not(:disabled) {
  background: #b91c1c;
}

.btn-outline {
  background: transparent;
  border-color: var(--border-color);
  color: var(--text-primary);
}
.btn-outline:hover:not(:disabled) {
  background: var(--bg-surface-alt);
}

.btn-danger-outline {
  background: transparent;
  border-color: var(--danger-border);
  color: var(--danger-color);
}
.btn-danger-outline:hover:not(:disabled) {
  background: var(--danger-bg);
}

.btn-neutral-outline {
  background: transparent;
  border-color: var(--border-color);
  color: var(--text-secondary);
}
.btn-neutral-outline:hover:not(:disabled) {
  background: var(--bg-surface-alt);
}

.btn-sm {
  padding: 0.35rem 0.65rem;
  font-size: 0.8rem;
}

.btn-block {
  width: 100%;
}

/* Funnel Section */
.vacancy-section {
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 1.25rem 1.5rem;
  box-shadow: var(--shadow-sm);
}

.section-header {
  margin-bottom: 1rem;
}

.section-title {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--text-primary);
}

.section-sub {
  font-size: 0.8rem;
  color: var(--text-muted);
}

/* D3 Funnel Styles */
.funnel-container {
  width: 100%;
  overflow-x: auto;
}

.funnel-chart-wrapper {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.funnel-svg {
  width: 100%;
  height: auto;
  max-height: 260px;
}

.grid-lines line {
  stroke: var(--border-color);
  stroke-dasharray: 3, 3;
}

.funnel-bar-reached {
  fill: var(--primary-color);
  opacity: 0.85;
}

.funnel-bar-remain {
  fill: var(--success-color);
}

.stage-applied .funnel-bar-reached { fill: #0284c7; }
.stage-screening .funnel-bar-reached { fill: #d97706; }
.stage-interview .funnel-bar-reached { fill: #7c3aed; }
.stage-offer .funnel-bar-reached { fill: #db2777; }
.stage-hired .funnel-bar-reached { fill: #059669; }

.funnel-val-label {
  fill: var(--text-primary);
  font-size: 12px;
  font-weight: 700;
}

.x-axis text {
  fill: var(--text-secondary);
  font-size: 12px;
  font-weight: 600;
}

.funnel-metrics-row {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(130px, 1fr));
  gap: 0.75rem;
}

.funnel-stage-card {
  background: var(--bg-surface-alt);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 0.65rem;
}

.stage-card-header {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.8rem;
  font-weight: 700;
  margin-bottom: 0.4rem;
}

.stage-dot {
  width: 8px;
  height: 8px;
  border-radius: var(--radius-full);
}

.stage-dot.applied { background: #0284c7; }
.stage-dot.screening { background: #d97706; }
.stage-dot.interview { background: #7c3aed; }
.stage-dot.offer { background: #db2777; }
.stage-dot.hired { background: #059669; }

.stage-card-stats {
  display: flex;
  justify-content: space-between;
  font-size: 0.72rem;
}

.stat-item {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.stat-num {
  font-weight: 700;
  font-size: 0.95rem;
  color: var(--text-primary);
}

.stat-num.active-val { color: var(--success-color); }
.stat-num.lost-val { color: var(--danger-color); }

.stat-lbl {
  color: var(--text-muted);
  font-size: 0.68rem;
  text-transform: uppercase;
}

.funnel-empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 2.5rem 1.5rem;
  text-align: center;
  background: var(--bg-surface-alt);
  border: 2px dashed var(--border-color);
  border-radius: var(--radius-md);
}

.empty-state-icon {
  color: var(--text-muted);
  margin-bottom: 0.75rem;
}

.empty-state-text strong {
  font-size: 1.1rem;
  color: var(--text-primary);
  display: block;
  margin-bottom: 0.25rem;
}

.empty-state-text p {
  font-size: 0.85rem;
  color: var(--text-muted);
  max-width: 480px;
  margin-bottom: 1.25rem;
}

.funnel-empty-grid {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
  justify-content: center;
}

.funnel-empty-stage {
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  padding: 0.4rem 0.85rem;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.empty-stage-name {
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--text-secondary);
}

.empty-stage-val {
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--text-muted);
}

/* View Switch Tabs */
.view-switch-tabs {
  display: flex;
  gap: 0.5rem;
  border-bottom: 1px solid var(--border-color);
  padding-bottom: 0.25rem;
}

.view-tab-btn {
  background: transparent;
  border: none;
  border-bottom: 3px solid transparent;
  padding: 0.5rem 1rem;
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text-secondary);
  cursor: pointer;
  transition: all 0.15s ease;
}

.view-tab-btn:hover {
  color: var(--text-primary);
}

.view-tab-btn.active {
  color: var(--primary-color);
  border-bottom-color: var(--primary-color);
}

/* Pipeline Board Grid */
.pipeline-stages-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 1rem;
  align-items: start;
}

.pipeline-column {
  background: var(--bg-surface-alt);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 0.75rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  min-height: 240px;
}

.col-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--text-secondary);
  padding: 0.25rem 0.35rem;
  border-bottom: 2px solid var(--border-color);
}

.col-count {
  background: var(--border-color);
  padding: 0.1rem 0.45rem;
  border-radius: var(--radius-full);
  font-size: 0.75rem;
  color: var(--text-primary);
}

.col-cards-list {
  display: flex;
  flex-direction: column;
  gap: 0.65rem;
}

.col-empty-card {
  font-size: 0.8rem;
  color: var(--text-muted);
  text-align: center;
  padding: 1.5rem 0.5rem;
  border: 1px dashed var(--border-subtle);
  border-radius: var(--radius-sm);
}

/* Candidate Card */
.candidate-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 0.85rem;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
  box-shadow: var(--shadow-sm);
  transition: all 0.15s ease;
}

.candidate-card:hover {
  border-color: var(--primary-border);
  box-shadow: var(--shadow-md);
  transform: translateY(-1px);
}

.candidate-card:focus-visible {
  outline: 2px solid var(--primary-color);
}

.card-top-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
}

.cand-name {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--text-primary);
}

.cand-id {
  font-size: 0.75rem;
  color: var(--text-muted);
  font-family: monospace;
}

.card-meta-row {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.75rem;
}

.cand-stage-pill {
  padding: 0.1rem 0.45rem;
  border-radius: var(--radius-sm);
  font-weight: 600;
  text-transform: capitalize;
}

.cand-stage-pill.stage-applied { background: var(--stage-applied-bg); color: var(--stage-applied-color); }
.cand-stage-pill.stage-screening { background: var(--stage-screening-bg); color: var(--stage-screening-color); }
.cand-stage-pill.stage-interview { background: var(--stage-interview-bg); color: var(--stage-interview-color); }
.cand-stage-pill.stage-offer { background: var(--stage-offer-bg); color: var(--stage-offer-color); }
.cand-stage-pill.stage-hired { background: var(--stage-hired-bg); color: var(--stage-hired-color); }
.cand-stage-pill.stage-rejected { background: var(--stage-rejected-bg); color: var(--stage-rejected-color); }
.cand-stage-pill.stage-withdrawn { background: var(--stage-withdrawn-bg); color: var(--stage-withdrawn-color); }

.cand-version-pill {
  background: var(--bg-surface-alt);
  border: 1px solid var(--border-color);
  padding: 0.1rem 0.35rem;
  border-radius: var(--radius-sm);
  color: var(--text-muted);
}

.cand-days {
  color: var(--text-muted);
  margin-left: auto;
}

.card-readiness-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.75rem;
  background: var(--bg-surface-alt);
  padding: 0.25rem 0.45rem;
  border-radius: var(--radius-sm);
}

.readiness-pill.ready {
  color: var(--success-color);
  font-weight: 700;
}

.readiness-pill.blocked {
  color: var(--warning-color);
  font-weight: 700;
}

.score-summary {
  color: var(--text-secondary);
  font-size: 0.72rem;
}

.card-panel-row {
  font-size: 0.75rem;
  color: var(--text-secondary);
  display: flex;
  align-items: center;
  gap: 0.35rem;
}

.card-notes-count {
  font-size: 0.72rem;
  color: var(--text-muted);
}

/* Candidate Drawer */
.drawer-root.open {
  display: block;
}

.drawer-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.45);
  backdrop-filter: blur(2px);
  z-index: 50;
}

.drawer-content {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  width: 100%;
  max-width: 580px;
  background: var(--bg-surface);
  border-left: 1px solid var(--border-color);
  z-index: 60;
  display: flex;
  flex-direction: column;
  box-shadow: var(--shadow-xl);
  overflow: hidden;
}

.drawer-header {
  padding: 1.25rem 1.5rem;
  border-bottom: 1px solid var(--border-color);
  background: var(--bg-surface-elevated);
  position: relative;
}

.drawer-header-meta {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 0.4rem;
}

.cand-id-badge {
  font-family: monospace;
  font-size: 0.8rem;
  background: var(--bg-surface-alt);
  padding: 0.15rem 0.45rem;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-color);
}

.cand-stage-badge {
  font-size: 0.75rem;
  font-weight: 700;
  padding: 0.15rem 0.5rem;
  border-radius: var(--radius-sm);
}

.cand-version-badge {
  font-size: 0.75rem;
  background: var(--primary-subtle);
  color: var(--primary-color);
  padding: 0.15rem 0.45rem;
  border-radius: var(--radius-sm);
  font-weight: 600;
}

.drawer-title {
  font-size: 1.4rem;
  font-weight: 800;
  color: var(--text-primary);
  margin-bottom: 0.25rem;
}

.drawer-subtitle {
  font-size: 0.85rem;
  color: var(--text-muted);
  display: flex;
  gap: 0.5rem;
  align-items: center;
}

.drawer-close-btn {
  position: absolute;
  top: 1.25rem;
  right: 1.5rem;
  background: transparent;
  border: none;
  font-size: 1.6rem;
  color: var(--text-muted);
  cursor: pointer;
  line-height: 1;
}

.drawer-close-btn:hover {
  color: var(--text-primary);
}

.drawer-body {
  padding: 1.5rem;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.drawer-section {
  background: var(--bg-surface-alt);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 1rem 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.section-heading {
  font-size: 1rem;
  font-weight: 700;
  color: var(--text-primary);
}

.section-heading-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.section-hint {
  font-size: 0.8rem;
  color: var(--text-muted);
  line-height: 1.4;
}

.version-tag {
  font-size: 0.75rem;
  font-weight: 700;
  background: var(--primary-subtle);
  color: var(--primary-color);
  padding: 0.2rem 0.5rem;
  border-radius: var(--radius-full);
}

/* Stage Stepper */
.stage-stepper {
  display: flex;
  justify-content: space-between;
  position: relative;
  margin-top: 0.5rem;
}

.step-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.25rem;
  z-index: 2;
}

.step-circle {
  width: 24px;
  height: 24px;
  border-radius: var(--radius-full);
  background: var(--bg-surface);
  border: 2px solid var(--border-subtle);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--text-muted);
}

.step-item.visited .step-circle {
  background: var(--primary-color);
  border-color: var(--primary-color);
  color: #fff;
}

.step-item.current .step-circle {
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px var(--primary-subtle);
}

.step-name {
  font-size: 0.72rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: capitalize;
}

.step-item.current .step-name {
  color: var(--primary-color);
  font-weight: 700;
}

/* Offer Readiness Card */
.offer-readiness-card {
  border-width: 2px;
}

.offer-readiness-card.ready {
  border-color: var(--success-border);
  background: var(--success-bg);
}

.offer-readiness-card.blocked {
  border-color: var(--warning-border);
  background: var(--warning-bg);
}

.readiness-header {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.readiness-badge {
  font-size: 0.8rem;
  font-weight: 800;
  padding: 0.25rem 0.6rem;
  border-radius: var(--radius-sm);
}

.badge-ready {
  background: var(--success-color);
  color: #fff;
}

.badge-blocked {
  background: var(--warning-color);
  color: #fff;
}

.readiness-summary {
  font-size: 0.85rem;
  color: var(--text-primary);
  font-weight: 600;
}

.blocked-reasons-list {
  margin-left: 1.25rem;
  font-size: 0.82rem;
  color: var(--text-secondary);
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
}

/* Action buttons group */
.action-buttons-group {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.role-notice {
  font-size: 0.82rem;
  color: var(--text-muted);
  background: var(--bg-surface);
  padding: 0.5rem 0.75rem;
  border-radius: var(--radius-sm);
  border: 1px dashed var(--border-color);
}

.frozen-banner {
  background: var(--bg-surface);
  padding: 0.5rem 0.75rem;
  border-radius: var(--radius-sm);
  font-size: 0.82rem;
  color: var(--text-muted);
  border: 1px solid var(--border-color);
}

/* Score Cards */
.scores-list {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.score-card {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: var(--bg-surface);
  padding: 0.6rem 0.85rem;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-color);
}

.score-card-member {
  display: flex;
  flex-direction: column;
}

.member-email {
  font-size: 0.75rem;
  color: var(--text-muted);
}

.score-badge {
  font-size: 0.82rem;
  font-weight: 700;
  padding: 0.2rem 0.5rem;
  border-radius: var(--radius-sm);
}

.score-badge.val-5, .score-badge.val-4 {
  background: var(--success-bg);
  color: var(--success-color);
  border: 1px solid var(--success-border);
}

.score-badge.val-3 {
  background: var(--warning-bg);
  color: var(--warning-color);
  border: 1px solid var(--warning-border);
}

.score-badge.val-2, .score-badge.val-1 {
  background: var(--danger-bg);
  color: var(--danger-color);
  border: 1px solid var(--danger-border);
}

.score-badge.val-pending {
  background: var(--bg-surface-alt);
  color: var(--text-muted);
  border: 1px dashed var(--border-subtle);
}

.submit-score-box {
  background: var(--bg-surface);
  border: 1px solid var(--primary-border);
  border-radius: var(--radius-sm);
  padding: 0.75rem;
  margin-top: 0.75rem;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.score-input-row {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.score-radios {
  display: flex;
  gap: 0.4rem;
}

.score-radio-label {
  width: 32px;
  height: 32px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  font-weight: 700;
  font-size: 0.9rem;
  background: var(--bg-surface-alt);
}

.score-radio-label input {
  display: none;
}

.score-radio-label.selected, .score-radio-label:has(input:checked) {
  background: var(--primary-color);
  color: #fff;
  border-color: var(--primary-color);
}

/* Historical Scores */
.historical-scores-section {
  margin-top: 0.85rem;
  border-top: 1px dashed var(--border-color);
  padding-top: 0.75rem;
}

.sub-heading {
  font-size: 0.88rem;
  font-weight: 700;
  color: var(--text-secondary);
  margin-bottom: 0.4rem;
}

.historical-scores-list {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.historical-score-item {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  font-size: 0.8rem;
  background: var(--bg-surface);
  padding: 0.4rem 0.65rem;
  border-radius: var(--radius-sm);
  color: var(--text-muted);
}

.hist-version {
  font-weight: 600;
  color: var(--text-secondary);
}

.hist-tag {
  margin-left: auto;
  font-size: 0.7rem;
  background: var(--bg-surface-alt);
  padding: 0.1rem 0.35rem;
  border-radius: var(--radius-sm);
}

/* Panel Section */
.panel-members-list {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.panel-member-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: var(--bg-surface);
  padding: 0.5rem 0.75rem;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-color);
}

.member-info {
  display: flex;
  flex-direction: column;
}

.member-name {
  font-weight: 600;
  font-size: 0.85rem;
}

.add-panel-box {
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  padding: 0.75rem;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.add-panel-controls {
  display: flex;
  gap: 0.5rem;
}

.form-select, .form-input, .form-textarea {
  width: 100%;
  padding: 0.45rem 0.65rem;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  background: var(--bg-surface);
  color: var(--text-primary);
  font-family: inherit;
  font-size: 0.85rem;
}

.form-select:focus, .form-input:focus, .form-textarea:focus {
  border-color: var(--primary-color);
  outline: none;
}

/* Notes Section */
.notes-list {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  max-height: 200px;
  overflow-y: auto;
}

.note-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  padding: 0.6rem 0.75rem;
}

.note-meta {
  display: flex;
  justify-content: space-between;
  font-size: 0.75rem;
  color: var(--text-muted);
  margin-bottom: 0.25rem;
}

.note-text {
  font-size: 0.85rem;
  color: var(--text-primary);
}

.add-note-box {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

/* Modal Dialogs */
.modal-root.open {
  display: block;
}

.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.55);
  backdrop-filter: blur(2px);
  z-index: 70;
}

.modal-dialog {
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 90%;
  max-width: 680px;
  max-height: 85vh;
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  z-index: 80;
  box-shadow: var(--shadow-xl);
