const puppeteer = require('puppeteer-core');
const { spawn } = require('child_process');

async function test() {
  const server = spawn('node', ['backend/server.js'], { env: { ...process.env, PORT: '3002' } });
  await new Promise(r => setTimeout(r, 1000));

  const browser = await puppeteer.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox'] });
  const page = await browser.newPage();
  page.on('console', msg => console.log('PAGE LOG:', msg.type(), msg.text()));
  page.on('pageerror', err => console.log('PAGE ERROR:', err.message));
  page.on('response', res => console.log('RESP:', res.status(), res.url()));

  await page.goto('http://127.0.0.1:3002/');
  console.log('Clicking demo button...');
  await page.click('.demo-account-btn[data-email="hiring@pellmoor.test"]');
  await new Promise(r => setTimeout(r, 1500));

  const html = await page.$eval('#app-root', el => el.innerHTML);
  console.log('App HTML after login:', html.substring(0, 300));

  await browser.close();
  server.kill();
}

test().catch(console.error);

